// ── /study/math — a mental-maths sprint coach + formulas + word problems ─────
function studyMathPage() {
  const formulas = [
    ['Circle', 'C = 2\u03c0r   \u00b7   A = \u03c0r\u00b2'],
    ['Rectangle', 'Perimeter = 2(l + w)   \u00b7   Area = l \u00d7 w'],
    ['Triangle area', 'A = \u00bd \u00d7 base \u00d7 height'],
    ['Pythagoras', 'a\u00b2 + b\u00b2 = c\u00b2 (right triangles)'],
    ['Volume of a box', 'V = l \u00d7 w \u00d7 h'],
    ['Sphere', 'V = \u2044\u2083 \u03c0r\u00b3   \u00b7   A = 4\u03c0r\u00b2'],
    ['Quadratic formula', 'x = (\u2212b \u00b1 \u221a(b\u00b2 \u2212 4ac)) / 2a'],
    ['Simple interest', 'I = P \u00d7 r \u00d7 t'],
    ['Percentage change', '(new \u2212 old) / old \u00d7 100%'],
    ['Average (mean)', 'sum of values \u00f7 number of values'],
    ['Speed', 'speed = distance \u00f7 time'],
    ['Density', 'density = mass \u00f7 volume'],
  ].map((f) => `<tr><td><b>${escapeHtml(f[0])}</b></td><td>${escapeHtml(f[1])}</td></tr>`).join('');
  const body = `<p class="learn-intro">Maths is a muscle: quick daily drills build the number sense that makes everything else easier. Use the sprint trainer below for two minutes a day, keep the formula sheet for reference, and read the stories to see why the numbers matter. Pair with the <a href="/study/science">science explainers</a> for the physics that uses these tools.</p>
  <h2 class="section-title">Mental-math sprint \u2014 60 seconds</h2>
  <p>Pick a level, press Start, and answer as many as you can before the clock runs out. Every problem is generated fresh in your browser.</p>
  <div class="quiz-block">
    <label for="mathlevel">Level:</label>
    <select id="mathlevel"><option value="add">Addition (easy)</option><option value="sub">Subtraction (easy)</option><option value="mul">Multiplication (medium)</option><option value="mix">Mixed (hard)</option></select>
    <button type="button" class="btn primary" id="mathstart">Start</button>
  </div>
  <div class="quiz-block" id="mathplay" style="display:none">
    <p class="meta">Time left: <b id="mathtime">60</b>s \u00b7 Score: <b id="mathscore">0</b></p>
    <p style="font-size:1.6rem;font-weight:700" id="mathq">\u2014</p>
    <input id="mathans" type="number" inputmode="numeric" aria-label="Your answer" style="padding:9px 12px;border:1px solid var(--line);border-radius:8px;background:var(--panel,#171a21);color:inherit;font-size:1.1rem;width:140px">
    <button type="button" class="btn primary" id="mathcheck">Check</button>
    <span id="mathfb" class="meta" aria-live="polite"></span>
  </div>
  <h2 class="section-title">The formula sheet</h2>
  <table class="study-table"><thead><tr><th>Thing</th><th>Formula</th></tr></thead><tbody>${formulas}</tbody></table>
  <h2 class="section-title">Numbers with a story</h2>
  <p>&bull; Zero became a number in India by the 7th century \u2014 before that, "nothing" was not something you could count with.</p>
  <p>&bull; A shuffled deck of 52 cards has about 8\u00d710<sup>67</sup> possible orders \u2014 more than the seconds since the Big Bang, so your shuffle has almost certainly never happened before.</p>
  <p>&bull; The Babylonians knew the Pythagorean relationship over a thousand years before Pythagoras; a clay tablet (Plimpton 322, c. 1800 BC) lists correct triples.</p>
  <p>&bull; Every map ever drawn needs at most four colours \u2014 the Four Colour Theorem, proven with a computer in 1976.</p>
  <script>(function(){var level=document.getElementById('mathlevel');var startBtn=document.getElementById('mathstart');var play=document.getElementById('mathplay');var qEl=document.getElementById('mathq');var ans=document.getElementById('mathans');var checkBtn=document.getElementById('mathcheck');var fb=document.getElementById('mathfb');var timeEl=document.getElementById('mathtime');var scoreEl=document.getElementById('mathscore');var current=0,left=60,score=0,timer=null;function rint(n){return Math.floor(Math.random()*n);}function make(){var t=level.value;if(t==='mix'){t=['add','sub','mul'][rint(3)];}var a,b;if(t==='add'){a=rint(50)+1;b=rint(50)+1;current=a+b;qEl.textContent=a+' + '+b+' =';}else if(t==='sub'){a=rint(80)+20;b=rint(a);current=a-b;qEl.textContent=a+' \u2212 '+b+' =';}else{a=rint(12)+2;b=rint(12)+2;current=a*b;qEl.textContent=a+' \u00d7 '+b+' =';}ans.value='';fb.textContent='';ans.focus();}function stop(){if(timer){clearInterval(timer);timer=null;}}startBtn.addEventListener('click',function(){play.style.display='block';left=60;score=0;scoreEl.textContent='0';timeEl.textContent='60';stop();make();timer=setInterval(function(){left--;timeEl.textContent=String(left);if(left<=0){stop();qEl.textContent="Time! You scored "+score;fb.textContent='';play.style.display='none';}},1000);});function judge(){var v=parseInt(ans.value,10);if(String(v)===String(current)){score++;scoreEl.textContent=String(score);fb.textContent='Correct';}else{fb.textContent='Not quite \u2014 it was '+current;}make();}checkBtn.addEventListener('click',judge);ans.addEventListener('keydown',function(e){if(e.key==='Enter'){judge();}});})();</script>`;
  return studyDoc({
    title: 'Mental Math Trainer \u2014 60-Second Sprint, Formulas & Number Facts | Tukuk-OS',
    desc: 'A free in-browser mental-math sprint game with addition, subtraction, multiplication and mixed levels, plus a formula sheet and the stories behind the numbers.',
    selfUrl: 'https://tukuk.org/study/math',
    heroTitle: 'Math \u2014 Fast and Faithful', heroSub: 'Drill your number sense, keep the formulas, meet the stories',
    body,
  });
}

// ── /study/alarm — the clock + alarm + pomodoro (honest: the tab must stay open) ──
function studyAlarmPage() {
  const body = `<p class="learn-intro">A no-install alarm clock and study timer that run entirely in your browser \u2014 nothing leaves this page. <b>Keep this tab open</b> for an alarm or countdown to fire; browsers do not let a closed tab ring. For the pomodoro technique, run a 25-minute focus block, take a 5-minute break, repeat.</p>
  <div class="quiz-block" style="text-align:center">
    <div id="bigclock" aria-live="off">--:--:--</div>
    <p class="meta" id="clockdate"></p>
    <button type="button" class="btn ghost" id="soundbtn">\uD83D\uDD0A Enable sound</button>
    <span class="meta" id="soundstate"> (click so the alarm can play)</span>
  </div>
  <div class="study-grid">
    <div class="study-card"><h3>\u23F0 Alarm</h3>
      <label for="alarmtime">Wake at:</label>
      <input id="alarmtime" type="time" style="padding:8px;border:1px solid var(--line);border-radius:8px;background:var(--panel,#171a21);color:inherit">
      <p><button type="button" class="btn primary" id="alarmtoggle">Set alarm</button> <span class="meta" id="alarmstate">Off</span></p>
    </div>
    <div class="study-card"><h3>\uD83C\uDF45 Pomodoro / countdown</h3>
      <p><button type="button" class="qbtn qopt" id="p25">25 min focus</button> <button type="button" class="qopt" id="p5">5 min break</button></p>
      <div style="font-size:1.8rem;font-weight:700" id="pdisplay">--:--</div>
      <p><button type="button" class="btn ghost" id="pstop">Stop</button></p>
    </div>
  </div>
  <p class="meta">Tip: set your device to keep the screen awake while studying. This tool never sends your data anywhere \u2014 see <a href="/privacy">Privacy</a>.</p>
  <script>(function(){var ac=null;var clk=document.getElementById('bigclock');var cdate=document.getElementById('clockdate');function pad(n){return (n<10?'0':'')+n;}var alarmOn=false,alarmAt='',alarmFired=false;function two(x){return x<10?'0'+x:''+x;}function tick(){var d=new Date();if(clk){clk.textContent=two(d.getHours())+':'+two(d.getMinutes())+':'+two(d.getSeconds());}if(cdate){cdate.textContent=d.toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric'});}var now=two(d.getHours())+':'+two(d.getMinutes());if(alarmOn&&alarmAt&&now===alarmAt&&!alarmFired){alarmFired=true;beepLoop();var s=document.getElementById('alarmstate');if(s){s.textContent='Ringing \u2014 dismiss to stop';}}}function beepLoop(){var n=0;var iv=setInterval(function(){beep();n++;if(n>40){clearInterval(iv);}},700);window.__stopbeep=function(){clearInterval(iv);};}function beep(){if(!ac)return;try{var o=ac.createOscillator();var g=ac.createGain();o.connect(g);g.connect(ac.destination);o.type='sine';o.frequency.value=880;g.gain.setValueAtTime(0.001,ac.currentTime);g.gain.exponentialRampToValueAtTime(0.2,ac.currentTime+0.02);g.gain.exponentialRampToValueAtTime(0.0001,ac.currentTime+0.4);o.start();o.stop(ac.currentTime+0.45);}catch(e){}}var sb=document.getElementById('soundbtn');if(sb){sb.addEventListener('click',function(){if(!ac){try{ac=new (window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(ac&&ac.resume){ac.resume();}document.getElementById('soundstate').textContent=' \u2713 ready';});}var tt=document.getElementById('alarmtoggle');if(tt){tt.addEventListener('click',function(){var inp=document.getElementById('alarmtime');var st=document.getElementById('alarmstate');if(alarmOn){alarmOn=false;st.textContent='Off';if(window.__stopbeep){window.__stopbeep();}return;}if(!inp.value){st.textContent='Pick a time first';return;}alarmAt=inp.value;alarmOn=true;alarmFired=false;st.textContent='On for '+alarmAt+' (keep this tab open)';});}var pdisp=document.getElementById('pdisplay');var pleft=0,ptimer=null;function pstop(){if(ptimer){clearInterval(ptimer);ptimer=null;}if(window.__stopbeep){window.__stopbeep();}}function render(){var m=Math.floor(pleft/60);var s=pleft%60;pdisp.textContent=(m<10?'0':'')+m+':'+(s<10?'0':'')+s;}function startP(secs){pstop();pleft=secs;render();ptimer=setInterval(function(){pleft--;render();if(pleft<=0){pstop();beep();beep();pdisp.textContent='Done!';}},1000);}var b25=document.getElementById('p25');if(b25){b25.addEventListener('click',function(){startP(25*60);});}var b5=document.getElementById('p5');if(b5){b5.addEventListener('click',function(){startP(5*60);});}var pstopBtn=document.getElementById('pstop');if(pstopBtn){pstopBtn.addEventListener('click',function(){pstop();pdisp.textContent='--:--';});}tick();setInterval(tick,1000);})();</script>`;
  return studyDoc({
    title: 'Alarm Clock & Pomodoro Timer \u2014 Free Browser Tool | Tukuk-OS',
    desc: 'A no-install alarm clock and 25/5 pomodoro study timer that runs in your browser with sound. Set a wake time, start a focus block, keep your data on-device.',
    selfUrl: 'https://tukuk.org/study/alarm',
    heroTitle: 'Alarm & Timer', heroSub: 'Wake-up alarm and pomodoro study timer \u2014 private, in-browser, no install',
    body,
  });
}

// ── The /study routes — all literals; geography is async (REAL country data). ────
app.get('/study', (req, res) => res.type('html').send(studyHubPage()));
app.get('/study/science', (req, res) => res.type('html').send(studySciencePage()));
app.get('/study/history', (req, res) => res.type('html').send(studyHistoryPage()));
app.get('/study/experiments', (req, res) => res.type('html').send(studyExperimentsPage()));
app.get('/study/riddles', (req, res) => res.type('html').send(studyRiddlesPage()));
app.get('/study/facts', (req, res) => res.type('html').send(studyFactsPage()));
app.get('/study/math', (req, res) => res.type('html').send(studyMathPage()));
app.get('/study/alarm', (req, res) => res.type('html').send(studyAlarmPage()));
app.get('/study/geography', async (req, res) => {
  let rows = null;
  try { rows = await ng.loadCountries(); } catch (e) { rows = null; }
  res.type('html').send(studyGeographyPage(Array.isArray(rows) && rows.length >= 20 ? rows : null));
});

// ══ UDARA COMPLEX /udara — world AQI readings + live CO2 + oxygen education ══
const UDARA_SECTIONS = [
  { href: '/udara', icon: '\uD83C\uDF0D', name: 'World Air Ranking', blurb: 'Live air quality for 70+ cities — the cleanest and dirtiest spots on Earth right now.' },
  { href: '/udara/carbon', icon: '\uD83D\uDDA2', name: 'Carbon Dioxide Live', blurb: 'Today\u2019s actual CO2 reading from NOAA\u2019s Mauna Loa observatory, with the 65-year climb.' },
  { href: '/udara/oxygen', icon: '\uD83E\uDEE9', name: 'Oxygen Explained', blurb: 'Where your oxygen really comes from, why it is falling, and what altitude does to a breath.' },
  { href: '/udara/breath', icon: '\uD83E\uDEC1', name: 'Breathing Life', blurb: 'From blue whales to houseflies: how every creature moves air, and what your own breath is doing.' },
];

function udaraNav() {
  return `<nav aria-label="Air and oxygen sections"><h2 class="section-title">Explore the Air & Oxygen Complex</h2><div class="feed">`
    + UDARA_SECTIONS.map((s) => `<div class="post-card"><h2><a href="${s.href}">${s.icon} ${s.name}</a></h2><p>${s.blurb}</p></div>`).join('')
    + `</div></nav>`;
}

// The standard /udara wrapper — mirrors studyDoc (full chrome + gated ads).
function udaraDoc(o) {
  const robots = o.robots || 'index,follow';
  const ld = o.ld || JSON.stringify({
    '@context': 'https://schema.org', '@type': 'CollectionPage', name: o.title,
    description: o.desc, url: o.selfUrl,
    publisher: { '@type': 'Organization', name: 'Tukuk-OS', url: 'https://tukuk.org' },
  }).replace(/</g, '\\u003c');
  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(o.title)}</title>
<meta name="description" content="${escapeHtml(o.desc)}">
<meta name="robots" content="${robots}">
<meta property="og:type" content="website">
<meta property="og:site_name" content="Tukuk-OS">
<meta property="og:title" content="${escapeHtml(o.title)}">
<meta property="og:description" content="${escapeHtml(o.desc)}">
<meta property="og:url" content="${o.selfUrl}">
<meta property="og:image" content="https://tukuk.org/og.png">
<meta name="twitter:card" content="summary_large_image">
<link rel="canonical" href="${o.selfUrl}">
<meta name="google-adsense-account" content="ca-pub-8954948214333501">
<script type="application/ld+json">${ld}</script>
<link rel="icon" href="/favicon.ico" sizes="48x48">
<link rel="icon" type="image/svg+xml" href="/icon.svg">
<link rel="apple-touch-icon" href="/apple-touch-icon.png">
<meta name="theme-color" content="#4c8dff">
<style>${COMMON_CSS}
.air-table{width:100%;border-collapse:collapse;font-size:.92rem;margin:14px 0}
.air-table th,.air-table td{border:1px solid var(--line);padding:8px 11px;text-align:left;vertical-align:top}
.air-table th{background:var(--panel,#171a21)}
.aqi-chip{display:inline-block;padding:3px 10px;border-radius:999px;font-weight:700;font-size:.82rem;color:#0f1115}
.aqi-chip.good{background:#3fb950}
.aqi-chip.moderate{background:#d29922}
.aqi-chip.usg{background:#f0883e}
.aqi-chip.unhealthy{background:#e5534b;color:#fff}
.aqi-chip.very{background:#a371f7;color:#fff}
.aqi-chip.hazardous{background:#8e1f2c;color:#fff}
.air-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px;margin:18px 0}
.air-card{border:1px solid var(--line);border-radius:10px;padding:16px 18px;background:var(--panel,#171a21);margin:0}
.air-card h3{margin:0 0 8px;font-size:1.05rem}
.air-card p{margin:6px 0;font-size:.95rem}
.big-readout{font-size:3rem;font-weight:800;letter-spacing:1px;margin:12px 0 4px}
.bar-row{display:flex;align-items:center;gap:8px;margin:3px 0;font-size:.86rem}
.bar-row .bl{min-width:44px;text-align:right;color:var(--muted,#9aa3b2)}
.bar-row .bv{min-width:70px}
.bar-row .bt{height:14px;border-radius:4px;background:var(--accent,#4c8dff);opacity:.85}
@media(max-width:680px){.air-grid{grid-template-columns:1fr}.air-table{display:block;overflow-x:auto}.big-readout{font-size:2.2rem}}
</style>
<script src="/theme.js"></script>
<link rel="stylesheet" href="/theme.css">
${pageAdScript()}${clarityScript()}
</head>
<body>
${siteHeader('learn')}
<div class="wrap">
  <header><h1>${o.heroHtml || escapeHtml(o.heroTitle || o.title)}</h1><p class="tagline">${escapeHtml(o.heroSub || '')}</p></header>
  <main>${adUnitGuarded(config.adsense.slotTop, 'top')}${msAdUnit('top')}
    ${o.body}
    ${adUnitGuarded(config.adsense.slotInArticle, 'in-article')}${msAdUnit('in-article')}
    ${udaraNav()}
    ${adUnitGuarded(config.adsense.slotBottom, 'bottom')}${msAdUnit('bottom')}
  </main>
</div>
${siteFooter()}
</body>
</html>`;
}

function aqiChip(v) {
  const c = udara.aqiCategory(v);
  if (!c) return '<span class="meta">\u2014</span>';
  return `<span class="aqi-chip ${c.cls}">${Math.round(v)} \u00b7 ${c.label}</span>`;
}
function airRow(r) {
  const n = (x, unit) => (x == null ? '\u2014' : x + (unit || ''));
  return `<tr><td><b>${escapeHtml(r.name)}</b>, ${escapeHtml(r.country)}</td><td>${escapeHtml(r.region)}</td><td>${aqiChip(r.usAqi)}</td><td>${n(r.pm25, ' \u00b5g/m\u00b3')}</td><td>${n(r.o3, ' \u00b5g/m\u00b3')}</td><td>${n(r.no2, ' \u00b5g/m\u00b3')}</td></tr>`;
}

// ── /udara — the live ranking; honest with source:'unavailable' when it is down ──
function udaraHubPage(air, co2) {
  const scale = `<h2 class="section-title">Reading the scale (US AQI)</h2>
  <table class="air-table"><thead><tr><th>Number</th><th>What it means</th></tr></thead><tbody>
  <tr><td>0\u201350</td><td>${aqiChip(30)} \u2014 air quality satisfactory for everyone.</td></tr>
  <tr><td>51\u2013100</td><td>${aqiChip(75)} \u2014 acceptable; unusually sensitive people should mind long outdoor effort.</td></tr>
  <tr><td>101\u2013150</td><td>${aqiChip(130)} \u2014 children, older adults and lung/heart conditions feel it first.</td></tr>
  <tr><td>151\u2013200</td><td>${aqiChip(170)} \u2014 everyone starts to notice; sensitive groups clearly affected.</td></tr>
  <tr><td>201\u2013300</td><td>${aqiChip(250)} \u2014 health effects likely; postpone hard outdoor exercise.</td></tr>
  <tr><td>301+</td><td>${aqiChip(350)} \u2014 emergency conditions; nearly everyone is affected.</td></tr>
  </tbody></table>`;
  const co2Card = co2 && co2.source && co2.source !== 'unavailable'
    ? `<div class="air-card"><h3>\uD83D\uDDA2 Carbon dioxide, right now</h3><p style="font-size:1.9rem;font-weight:800">${co2.ppm.toFixed(1)} ppm</p><p class="meta">NOAA ${escapeHtml(co2.site)} reading, ${escapeHtml(co2.date)} \u00b7 <a href="/udara/carbon">the full carbon story &rarr;</a></p></div>`
    : `<div class="air-card"><h3>\uD83D\uDDA2 Carbon dioxide, right now</h3><p style="font-size:1.9rem;font-weight:800">\u2014</p><p class="meta">The NOAA feed is briefly resting \u2014 the <a href="/udara/carbon">carbon page</a> explains and retries.</p></div>`;
  let data = '';
  if (air && air.rows && air.rows.length) {
    const rows = air.rows;
    const mid = Math.round(rows[Math.floor(rows.length / 2)].usAqi);
    const clean = rows.slice(0, 10).map(airRow).join('');
    const dirty = rows.slice(-10).reverse().map(airRow).join('');
    const all = rows.map((r, i) => `<tr><td>${i + 1}</td><td><b>${escapeHtml(r.name)}</b>, ${escapeHtml(r.country)}</td><td>${escapeHtml(r.region)}</td><td>${aqiChip(r.usAqi)}</td><td>${r.pm25 == null ? '\u2014' : r.pm25 + ' \u00b5g/m\u00b3'}</td></tr>`).join('');
    const note = air.source === 'last-known'
      ? `<p class="meta">\u26A0 The live feed is briefly unavailable \u2014 these are the last good readings, taken ${new Date(air.staleSince || air.fetchedAt).toISOString().slice(0, 16).replace('T', ' ')} UTC.</p>`
      : (air.source === 'partial'
        ? `<p class="meta">\u26A0 ${air.failedCount} of ${udara.CITIES.length} city readings failed this round; the rest are current.</p>`
        : (air.updating
          ? `<p class="meta">\u21BB A fresh scan is running in the background \u2014 this snapshot was taken ${new Date(air.fetchedAt).toISOString().slice(0, 16).replace('T', ' ')} UTC.</p>`
          : ''));
    data = `<div class="air-grid">
      <div class="air-card"><h3>\uD83C\uDF3F Cleanest spot right now</h3><p style="font-size:1.4rem;font-weight:800">${escapeHtml(rows[0].name)}, ${escapeHtml(rows[0].country)}</p><p>${aqiChip(rows[0].usAqi)}</p></div>
      <div class="air-card"><h3>\uD83D\uDD25 Dirtiest spot right now</h3><p style="font-size:1.4rem;font-weight:800">${escapeHtml(rows[rows.length - 1].name)}, ${escapeHtml(rows[rows.length - 1].country)}</p><p>${aqiChip(rows[rows.length - 1].usAqi)}</p></div>
      ${co2Card}
      <div class="air-card"><h3>Middle of the pack</h3><p style="font-size:1.4rem;font-weight:800">median AQI ${mid}</p><p class="meta">across ${rows.length} monitored world cities</p></div>
    </div>
    ${note}
    <h2 class="section-title">The ten cleanest points on Earth (of our network)</h2>
    <table class="air-table"><thead><tr><th>City</th><th>Region</th><th>US AQI</th><th>PM2.5</th><th>Ozone</th><th>NO2</th></tr></thead><tbody>${clean}</tbody></table>
    <h2 class="section-title">The ten dirtiest</h2>
    <table class="air-table"><thead><tr><th>City</th><th>Region</th><th>US AQI</th><th>PM2.5</th><th>Ozone</th><th>NO2</th></tr></thead><tbody>${dirty}</tbody></table>
    <details><summary style="cursor:pointer;font-weight:600;margin:10px 0">Full ranking \u2014 all ${rows.length} cities, cleanest to dirtiest</summary>
    <table class="air-table"><thead><tr><th>#</th><th>City</th><th>Region</th><th>US AQI</th><th>PM2.5</th></tr></thead><tbody>${all}</tbody></table></details>`;
  } else {
    const waitNote = air && air.source === 'starting'
      ? `<p class="meta">\u21BB First air scan of this server session is running right now — reload in about a minute and the full world ranking will be here.</p>`
      : `<p class="meta">\u26A0 The live world feed is resting right now — we would rather show you nothing than show you invented numbers. Reload in a few minutes; the scale below and every explainer on this complex always work.</p>`;
    data = `<div class="air-grid">${co2Card}</div>
    ${waitNote}`;
  }
  const body = `<p class="learn-intro">Live air-quality readings for over seventy world cities, modelled by the Copernicus Atmosphere Monitoring Service and delivered through the free Open-Meteo API, refreshed on our side every 45 minutes. These are model estimates for each city\u2019s coordinates \u2014 your street can differ; treat them as a global pulse, not a personal sensor. Weather for any of these cities lives at <a href="/cuaca">World Weather</a>.</p>
  ${data}
  ${scale}`;
  return udaraDoc({
    title: 'World Air Quality Live \u2014 Cleanest and Most Polluted Places on Earth | Tukuk-OS',
    desc: 'Live US AQI, PM2.5, ozone and NO2 readings for 70+ world cities ranked cleanest to dirtiest, plus today\u2019s real CO2 level from the NOAA Mauna Loa observatory.',
    selfUrl: 'https://tukuk.org/udara',
    heroTitle: 'The Air We Breathe \u2014 Live', heroSub: 'Clean spots, dirty spots and the carbon in the sky, updated from free open sources',
    body,
  });
}

// ── /udara/carbon — live NOAA CO2 readings ───────────────────────
function udaraCarbonPage(co2) {
  let readout = '';
  if (co2 && co2.source && co2.source !== 'unavailable') {
    const vmin = co2.annual[0] ? co2.annual[0].v - 2 : 400;
    const vmax = co2.annual[co2.annual.length - 1] ? co2.annual[co2.annual.length - 1].v + 2 : 430;
    const bars = co2.annual.map((a) => {
      const w = Math.max(4, Math.round(((a.v - vmin) / (vmax - vmin)) * 100));
      return `<div class="bar-row"><span class="bl">${a.year}</span><span class="bt" style="width:${w}%"></span><span class="bv">${a.v.toFixed(1)}</span></div>`;
    }).join('');
    const stale = co2.source === 'last-known' ? '<p class="meta">\u26A0 The NOAA feed is briefly unreachable \u2014 showing the last reading we successfully fetched.</p>' : '';
    readout = `<div class="air-grid">
      <div class="air-card"><h3>Today\u2019s reading</h3><p class="big-readout">${co2.ppm.toFixed(1)} <span style="font-size:1.1rem">ppm</span></p><p class="meta">Daily mean CO\u2082, NOAA ${escapeHtml(co2.site)} \u00b7 ${escapeHtml(co2.date)} \u00b7 refreshed every 12 h</p></div>
      <div class="air-card"><h3>The climb per year</h3><p class="big-readout">${co2.growth == null ? '\u2014' : '+' + co2.growth} <span style="font-size:1.1rem">ppm/yr</span></p><p class="meta">Latest global annual-mean step (NOAA). A natural year is about +1; fossil years run +2 to +3.</p></div>
    </div>
    ${stale}
    <h2 class="section-title">Fifteen years of the global annual mean</h2>
    <p>Parts per million of carbon dioxide in the whole-world surface atmosphere, year by year \u2014 straight from NOAA\u2019s global monitoring averages.</p>
    <div>${bars}</div>`;
  } else {
    readout = `<p class="meta">\u26A0 The NOAA carbon feed is resting right now and we keep no invented placeholder \u2014 reload in a few minutes for the real number.</p>`;
  }
  const body = `<p class="learn-intro">Carbon dioxide is the gas of breath and fire: every animal exhales it, every flame turns air into it, and for two centuries humans have been doing so at an industrial scale. This page shows the actual measurement \u2014 no model, no estimate: flasks and analysers at NOAA\u2019s Mauna Loa observatory in Hawaii and a global network, published freely.</p>
  ${readout}
  <h2 class="section-title">What the number means</h2>
  <div class="air-grid">
    <div class="air-card"><h3>280 \u2192 420+ in 170 years</h3><p>Before the industrial revolution the world\u2019s air held about 280 ppm of CO\u2082. NOAA\u2019s global annual means began in 1959 at roughly ${co2 && co2.base1958 ? co2.base1958.toFixed(1) : '316'} ppm and now pass 420 \u2014 a level at least three million years older than any human ancestor.</p></div>
    <div class="air-card"><h3>Why the sawtooth is not noise</h3><p>Northern forests and grasslands inhale CO\u2082 each summer and exhale it each winter, so the curve breathes seasonally by a handful of ppm while its baseline only climbs. The trend is the fingerprint of fossil carbon; the wobble is the living planet.</p></div>
    <div class="air-card"><h3>Your own contribution</h3><p>A person exhales air that is about 4 percent CO\u2082 \u2014 roughly 40,000 ppm against the outdoor 420. Every breath you have ever taken added carbon the food chain just captured from the air; the industrial loop is the same loop, run too fast.</p></div>
    <div class="air-card"><h3>Where to argue with the number</h3><p>CO\u2082 itself is not a poison at outdoor levels \u2014 it is 0.04 percent of air. Its weight is radiative: more of it holds more of the Earth\u2019s outgoing heat. That physics, not toxicity, is why this dial matters to every country on the coast.</p></div>
  </div>
  <h2 class="section-title">Related</h2>
  <p>How living things move this gas day by day: <a href="/udara/breath">Breathing Life</a>. The oxygen side of the same reaction: <a href="/udara/oxygen">Oxygen Explained</a>. City-by-city particulate and ozone readings: <a href="/udara">the world air ranking</a>.</p>`;
  return udaraDoc({
    title: 'CO2 Level Today, Live \u2014 The Real Mauna Loa Reading | Tukuk-OS',
    desc: 'Today\u2019s actual atmospheric carbon dioxide reading from NOAA\u2019s Mauna Loa observatory and global annual means, with plain-language context on the 280-to-420 ppm climb.',
    selfUrl: 'https://tukuk.org/udara/carbon',
    heroTitle: 'Carbon Dioxide, Read Directly', heroSub: 'The live number from NOAA \u2014 what it says and what it does not',
    body,
  });
}

// ── /udara/oxygen — O2 education (static curation) ─────────────────────
function udaraOxygenPage() {
  const cards = udara.OXYGEN.map((c) => `<div class="air-card"><h3>${escapeHtml(c.h)}</h3>${c.paras.map((p) => `<p>${escapeHtml(p)}</p>`).join('')}</div>`).join('');
  const myths = udara.MYTHS.map((m) => `<div class="air-card"><h3>Myth: ${escapeHtml(m.m)}</h3><p>${escapeHtml(m.f)}</p></div>`).join('');
  const body = `<p class="learn-intro">Oxygen is the most consequential chemical argument on Earth: it lets fires spread, lets animals run hot and lets brains afford to think. Below \u2014 where it comes from, where it is going, and how the planet has breathed differently across deep time. The live side of this story is the <a href="/udara">world air ranking</a> and the <a href="/udara/carbon">CO2 readout</a>.</p>
  <div class="air-grid">${cards}</div>
  <h2 class="section-title">Claims worth un-learning</h2>
  <div class="air-grid">${myths}</div>`;
  return udaraDoc({
    title: 'Oxygen Explained \u2014 Where It Comes From and Where It Is Going | Tukuk-OS',
    desc: 'Plain-language oxygen science: 20.9 percent air, phytoplankton as the real oxygen factory, the measured slow decline, altitude physiology and ocean oxygen minimum zones.',
    selfUrl: 'https://tukuk.org/udara/oxygen',
    heroTitle: 'Oxygen \u2014 The Argument Air Won', heroSub: 'The gas behind every flame, breath and giant insect in Earth history',
    body,
  });
}

// ── /udara/breath — how living things breathe ───────────────────────
function udaraBreathPage() {
  const human = udara.HUMAN_BREATH.map((r) => `<tr><td><b>${escapeHtml(r.k)}</b></td><td>${escapeHtml(r.v)}</td><td>${escapeHtml(r.note)}</td></tr>`).join('');
  const animals = udara.ANIMAL_BREATH.map((r) => `<tr><td><b>${escapeHtml(r.a)}</b></td><td>${escapeHtml(r.rr)}</td><td>${escapeHtml(r.note)}</td></tr>`).join('');
  const ways = udara.OTHER_WAYS.map((c) => `<div class="air-card"><h3>${escapeHtml(c.h)}</h3>${c.paras.map((p) => `<p>${escapeHtml(p)}</p>`).join('')}</div>`).join('');
  const indoor = udara.INDOOR_CO2.map((r) => `<tr><td><b>${escapeHtml(r.v)}</b></td><td>${escapeHtml(r.t)}</td><td>${escapeHtml(r.d)}</td></tr>`).join('');
  const body = `<p class="learn-intro">A breath looks simple and is one of the most negotiated transactions in biology: oxygen in, carbon dioxide out, paid for in energy. Here is what your own breathing budget looks like, how the animal kingdom solved the same problem, and where the air in your room sits on that ledger. Respiratory rates below are commonly cited resting ranges \u2014 individuals, sizes and temperatures move them.</p>
  <h2 class="section-title">Your breathing, by the numbers</h2>
  <table class="air-table"><thead><tr><th>Measure</th><th>Typical value</th><th>The human note</th></tr></thead><tbody>${human}</tbody></table>
  <h2 class="section-title">Resting breath across the animal kingdom</h2>
  <table class="air-table"><thead><tr><th>Animal</th><th>Resting breaths / pattern</th><th>Why it is interesting</th></tr></thead><tbody>${animals}</tbody></table>
  <h2 class="section-title">Other engineering for the same job</h2>
  <div class="air-grid">${ways}</div>
  <h2 class="section-title">The CO2 in the room you are reading this in</h2>
  <p>Air at ~420 ppm outdoors climbs in closed rooms simply because of the occupants. If a classroom feels dim by mid-morning, the ventilation \u2014 not the lesson \u2014 is usually the suspect: crack a window and watch the room wake up.</p>
  <table class="air-table"><thead><tr><th>Level</th><th>Where you are</th><th>What it does</th></tr></thead><tbody>${indoor}</tbody></table>`;
  return udaraDoc({
    title: 'How Living Things Breathe \u2014 Humans, Whales, Gills and Insects | Tukuk-OS',
    desc: 'Breathing explained across species: human respiratory numbers, resting rates of animals, whale dives, fish gills, insect tracheae, bird lungs and indoor CO2 levels.',
    selfUrl: 'https://tukuk.org/udara/breath',
    heroTitle: 'Breathing Life', heroSub: 'Twenty thousand times a day, without one decision \u2014 the engineering of a breath',
    body,
  });
}

app.get('/udara', async (req, res) => {
  const [air, co2] = await Promise.allSettled([udara.getAirRanking(), udara.getCo2()]);
  res.type('html').send(udaraHubPage(air.status === 'fulfilled' ? air.value : null, co2.status === 'fulfilled' ? co2.value : null));
});
app.get('/udara/oxygen', (req, res) => res.type('html').send(udaraOxygenPage()));
app.get('/udara/breath', (req, res) => res.type('html').send(udaraBreathPage()));
app.get('/udara/carbon', async (req, res) => {
  let co2 = null;
  try { co2 = await udara.getCo2(); } catch (e) { co2 = null; }
  res.type('html').send(udaraCarbonPage(co2));
});

// ══ TUKUK-OS AKADEMI (/akademi) — 50 micro-lessons of general knowledge: 10 tracks
// × 5 lessons (src/akademi.js, locally curated, in English). Unlike
// /learn (the developer curriculum) — this is world knowledge for everyone; every track
// it links the matching live tool. The shell mirrors studyDoc: full chrome + 3 ad units.
function akadNav() {
  const items = [{ href: '/akademi', icon: '\uD83C\uDF93', name: 'All 50 Lessons', blurb: 'The full syllabus — ten tracks, five short lessons each, no account needed.' }]
    .concat(akad.trackList().map((t) => ({ href: `/akademi/${t.s}`, icon: t.icon, name: t.name, blurb: t.blurb })));
  return `<nav aria-label="Academy tracks"><h2 class="section-title">Akademi Tukuk-OS — every track</h2><div class="feed">`
    + items.map((s) => `<div class="post-card"><h2><a href="${s.href}">${s.icon} ${s.name}</a></h2><p>${escapeHtml(s.blurb)}</p></div>`).join('')
    + `</div></nav>`;
}

// The standard /akademi page wrapper — mirrors studyDoc (full chrome + gated ads).
function akadDoc(o) {
  const robots = o.robots || 'index,follow';
  const ld = o.ld || JSON.stringify({
    '@context': 'https://schema.org', '@type': 'CollectionPage', name: o.title,
    description: o.desc, url: o.selfUrl,
    publisher: { '@type': 'Organization', name: 'Tukuk-OS', url: 'https://tukuk.org' },
  }).replace(/</g, '\\u003c');
  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(o.title)}</title>
<meta name="description" content="${escapeHtml(o.desc)}">
<meta name="robots" content="${robots}">
<meta property="og:type" content="website">
<meta property="og:site_name" content="Tukuk-OS">
<meta property="og:title" content="${escapeHtml(o.title)}">
<meta property="og:description" content="${escapeHtml(o.desc)}">
<meta property="og:url" content="${o.selfUrl}">
<meta property="og:image" content="https://tukuk.org/og.png">
<meta name="twitter:card" content="summary_large_image">
<link rel="canonical" href="${o.selfUrl}">
<meta name="google-adsense-account" content="ca-pub-8954948214333501">
<script type="application/ld+json">${ld}</script>
<link rel="icon" href="/favicon.ico" sizes="48x48">
<link rel="icon" type="image/svg+xml" href="/icon.svg">
<link rel="apple-touch-icon" href="/apple-touch-icon.png">
<meta name="theme-color" content="#4c8dff">
<style>${COMMON_CSS}
.akad-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px;margin:18px 0}
.akad-card{border:1px solid var(--line);border-radius:10px;padding:16px 18px;background:var(--panel,#171a21);margin:0}
.akad-card h3{margin:0 0 8px;font-size:1.05rem}
.akad-card p{margin:6px 0;font-size:.95rem}
.takeaway{border:1px solid var(--line);border-left:4px solid var(--accent,#4c8dff);border-radius:10px;padding:14px 18px;margin:20px 0;background:var(--panel,#171a21)}
.takeaway h2{margin:0 0 10px;font-size:1.05rem}
.takeaway ul{margin:0;padding-left:22px}
.takeaway li{margin-bottom:6px}
.lesson-nav{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;margin:26px 0 6px}
.qopt{display:inline-block;border:1px solid var(--line);background:var(--panel,#171a21);color:var(--text);border-radius:8px;padding:7px 13px;margin:4px 6px 4px 0;font-size:.92rem;cursor:pointer}
.qopt:hover{border-color:var(--accent,#4c8dff)}
.qopt.ok{border-color:#3fb950;color:#3fb950;font-weight:700}
.qopt.no{border-color:#e5534b;color:#e5534b}
.quiz-block{border:1px solid var(--line);border-radius:10px;padding:14px 16px;margin:14px 0;background:var(--panel,#171a21)}
@media(max-width:680px){.akad-grid{grid-template-columns:1fr}}
</style>
<script src="/theme.js"></script>
<link rel="stylesheet" href="/theme.css">
${pageAdScript()}${clarityScript()}
</head>
<body>
${siteHeader('learn')}
<div class="wrap">
  <header><h1>${o.heroHtml || escapeHtml(o.heroTitle || o.title)}</h1><p class="tagline">${escapeHtml(o.heroSub || '')}</p></header>
  <main>${adUnitGuarded(config.adsense.slotTop, 'top')}${msAdUnit('top')}
    ${o.body}
    ${adUnitGuarded(config.adsense.slotInArticle, 'in-article')}${msAdUnit('in-article')}
    ${akadNav()}
    ${adUnitGuarded(config.adsense.slotBottom, 'bottom')}${msAdUnit('bottom')}
  </main>
</div>
${siteFooter()}
</body>
</html>`;
}

// ── /akademi — the hub: a grid of 10 tracks + an honest total time on display ──────────────
function akadHubPage() {
  const flat = akad.allLessons();
  const totalMin = flat.reduce((n, l) => n + l.mn, 0);
  const cards = akad.trackList().map((t, i) => {
    const min = (akad.LESSONS[t.s] || []).reduce((n, l) => n + l.mn, 0);
    return `<div class="akad-card"><h3><a href="/akademi/${t.s}">${t.icon} ${escapeHtml(t.name)}</a></h3><p>${escapeHtml(t.blurb)}</p><p class="meta">Track ${i + 1} · 5 lessons · about ${min} min</p></div>`;
  }).join('');
  const body = `<p class="learn-intro">Fifty short lessons on how the world actually works — sky and space, weather, the planet, air, the body, life, numbers, computers, everyday machines and clear thinking. Each lesson is three plain-language paragraphs, three takeaways and one quiz question; the whole academy reads in about ${Math.round(totalMin / 60)} hours spread over a month. Free, no account, no paywall. For coding paths see the <a href="/learn">Zero-to-Hero Academy</a>; for daily facts and quizzes the <a href="/study">Knowledge Complex</a>.</p>
  <h2 class="section-title">The syllabus — ten tracks, fifty lessons</h2>
  <div class="akad-grid">${cards}</div>
  <p class="meta">Figures in the lessons are labelled “about” or “roughly” wherever sources differ — the academy prefers an honest approximation to a false decimal.</p>`;
  return akadDoc({
    title: 'Akademi Tukuk-OS — 50 Free Micro-Lessons on How the World Works',
    desc: 'A free general-knowledge academy: 50 short lessons across ten tracks — space, weather, Earth, air, body, life, numbers, internet, machines and clear thinking — each with takeaways and a quiz.',
    selfUrl: 'https://tukuk.org/akademi',
    heroTitle: 'Akademi Tukuk-OS', heroSub: 'Fifty lessons, ten tracks, one curiosity — how the world works, in plain language',
    body,
  });
}

// ── /akademi/:track — the 5 lessons + the track's live-tool link ──────────
// The extra-reading search topic for each track (Open Library + Crossref, keyless).
const TRACK_TOPIC = {
  sky: 'astronomy', weather: 'weather and climate', earth: 'geology of the Earth',
  air: 'the atmosphere and air quality', body: 'the human body', life: 'ecology and the living world',
  numbers: 'statistics and probability', internet: 'computers and the internet',
  things: 'engineering and invention', thinking: 'critical thinking',
};
async function akadTrackPage(t) {
  const lessons = akad.LESSONS[t.s] || [];
  const min = lessons.reduce((n, l) => n + l.mn, 0);
  const rows = lessons.map((l, i) => `<div class="akad-card"><h3><a href="/akademi/${t.s}/${l.s}">${i + 1}. ${escapeHtml(l.t)}</a></h3><p>${escapeHtml(l.sum)}</p><p class="meta">About ${l.mn} min · 1 quiz question</p></div>`).join('');
  const rel = `<h2 class="section-title">Try it live</h2><ul>${t.rel.map((r) => `<li><a href="${r.h}">${escapeHtml(r.l)}</a></li>`).join('')}</ul>`;
  // The reading box — external-source failures are dropped silently (each one catches → []).
  const topic = TRACK_TOPIC[t.s] || t.name;
  const [bk, pp] = await Promise.all([
    bacaan.books(topic, 3).catch(() => []),
    bacaan.papers(topic, 3).catch(() => []),
  ]);
  const bookBox = bk && bk.length
    ? `<h2 class="section-title">Further reading</h2><p>Three real books on this track, from the Open Library catalogue — follow the links for libraries, previews and borrow options.</p><div class="akad-grid">${bk.map((b) => `<div class="akad-card" style="display:flex;gap:14px;align-items:flex-start">${b.cover ? `<img src="${escapeHtml(b.cover)}" alt="Cover of ${escapeHtml(b.title)}" loading="lazy" style="width:64px;height:96px;object-fit:cover;border-radius:6px;border:1px solid var(--line)">` : ''}<div><h3><a rel="noopener nofollow" href="${escapeHtml(b.url)}">${escapeHtml(b.title)}</a></h3><p class="meta" style="margin:0">${escapeHtml(b.author)}${b.year ? ` · ${b.year}` : ''}</p></div></div>`).join('')}</div>`
    : '';
  const paperBox = pp && pp.length
    ? `<h2 class="section-title">The research</h2><p>The most-cited Crossref-indexed papers matching the topic — a window into how professionals actually study it.</p><ul>${pp.map((p) => `<li><a rel="noopener nofollow" href="${escapeHtml(p.url)}">${escapeHtml(p.title)}</a> — ${escapeHtml(p.author)}${p.year ? ` (${p.year})` : ''}, cited ${p.cites.toLocaleString('en-US')} times</li>`).join('')}</ul>`
    : '';
  const body = `<p class="learn-intro"><a href="/akademi">&larr; All 50 lessons</a></p>
  <p>${escapeHtml(t.blurb)} Five lessons, about ${min} minutes in total — read one at a time; each stands alone.</p>
  <div class="akad-grid">${rows}</div>
  ${rel}${bookBox}${paperBox}`;
  return akadDoc({
    title: `${t.name} — 5 Lessons | Akademi Tukuk-OS`,
    desc: `${t.blurb} Five short free lessons with key takeaways and quiz questions, from Akademi Tukuk-OS.`,
    selfUrl: `https://tukuk.org/akademi/${t.s}`,
    heroTitle: `${t.icon} ${t.name}`, heroSub: 'Five micro-lessons · about ' + min + ' minutes in total',
    body,
  });
}

// ── /akademi/:track/:slug — reading + teaching + a one-question quiz + prev/next ─
function akadLessonPage(t, l, prev, next, no) {
  const right = l.q.o[l.q.a];
  const quizHtml = `<h2 class="section-title">Check yourself</h2>
  <div class="quiz-block"><p><b>${escapeHtml(l.q.s)}</b></p>
    ${l.q.o.map((opt, i) => `<button type="button" class="qopt" data-ok="${i === l.q.a ? '1' : '0'}">${escapeHtml(opt)}</button>`).join('')}
    <div id="qexp" style="display:none;margin-top:12px"><p class="meta" style="margin:0 0 4px">Correct answer: <b>${escapeHtml(right)}</b></p><p style="margin:0">${escapeHtml(l.q.e)}</p></div>
  </div>
  <script>(function(){var b=document.querySelector('.quiz-block');if(!b)return;var done=false;Array.prototype.forEach.call(b.querySelectorAll('.qopt'),function(btn){btn.addEventListener('click',function(){if(done)return;done=true;var good=btn.getAttribute('data-ok')==='1';btn.className='qopt '+(good?'ok':'no');if(!good){Array.prototype.forEach.call(b.querySelectorAll('.qopt'),function(o){if(o.getAttribute('data-ok')==='1')o.className='qopt ok';});}var x=document.getElementById('qexp');if(x)x.style.display='block';});});})();</script>`;
  const relHtml = `<h2 class="section-title">Go deeper</h2><ul>${t.rel.map((r) => `<li><a href="${r.h}">${escapeHtml(r.l)}</a></li>`).join('')}<li><a href="/akademi/${t.s}">All ${t.name} lessons</a></li></ul>`;
  const lrMin = Math.max(1, Math.round(l.mn));
  const ld = JSON.stringify({
    '@context': 'https://schema.org', '@graph': [
      { '@type': 'LearningResource', name: l.t, description: l.sum, url: `https://tukuk.org/akademi/${t.s}/${l.s}`,
        inLanguage: 'en', learningResourceType: 'Micro-lesson', timeRequired: `PT${lrMin}M`,
        isPartOf: { '@type': 'Collection', name: `${t.name} track — Akademi Tukuk-OS`, url: `https://tukuk.org/akademi/${t.s}` },
        providesSerialization: { '@type': 'WebPage', id: `https://tukuk.org/akademi/${t.s}/${l.s}#main` },
        publisher: { '@type': 'Organization', name: 'Tukuk-OS', url: 'https://tukuk.org' } },
      { '@type': 'BreadcrumbList', itemListElement: [
        { '@type': 'ListItem', position: 1, name: 'Akademi', item: 'https://tukuk.org/akademi' },
        { '@type': 'ListItem', position: 2, name: t.name, item: `https://tukuk.org/akademi/${t.s}` },
        { '@type': 'ListItem', position: 3, name: l.t, item: `https://tukuk.org/akademi/${t.s}/${l.s}` } ] },
    ],
  }).replace(/</g, '\\u003c');
  const body = `<p class="learn-intro"><a href="/akademi">&larr; Akademi</a> · <a href="/akademi/${t.s}">${t.icon} ${escapeHtml(t.name)}</a> · Lesson ${no} of 50 · about ${l.mn} min</p>
  <article>${l.p.map((p) => `<p>${escapeHtml(p)}</p>`).join('')}</article>
  <div class="takeaway"><h2>Key takeaways</h2><ul>${l.k.map((k) => `<li>${escapeHtml(k)}</li>`).join('')}</ul></div>
  ${quizHtml}
  ${relHtml}
  <div class="lesson-nav">
    ${prev ? `<a class="btn ghost" href="/akademi/${prev.track.s}/${prev.s}">&larr; ${escapeHtml(prev.t)}</a>` : '<span></span>'}
    ${next ? `<a class="btn ghost" href="/akademi/${next.track.s}/${next.s}">${escapeHtml(next.t)} &rarr;</a>` : '<span></span>'}
  </div>`;
  return akadDoc({
    title: `${l.t} — ${t.name} Lesson | Akademi Tukuk-OS`,
    desc: l.sum,
    selfUrl: `https://tukuk.org/akademi/${t.s}/${l.s}`,
    heroTitle: l.t, heroSub: `${t.icon} ${t.name} · Lesson ${no} of 50 · about ${l.mn} minutes`,
    ld,
    body,
  });
}

app.get('/akademi', (req, res) => res.type('html').send(akadHubPage()));
app.get('/akademi/:track', async (req, res) => {
  const t = akad.findTrack(req.params.track);
  if (!t) return res.redirect('/akademi');
  res.type('html').send(await akadTrackPage(t));
});
app.get('/akademi/:track/:slug', (req, res) => {
  const t = akad.findTrack(req.params.track);
  const l = t && akad.findLesson(t.s, req.params.slug);
  if (!l) return res.redirect('/akademi');
  const flat = akad.allLessons();
  const idx = flat.findIndex((x) => x.track.s === t.s && x.s === l.s);
  res.type('html').send(akadLessonPage(t, l, idx > 0 ? flat[idx - 1] : null, idx < flat.length - 1 ? flat[idx + 1] : null, idx + 1));
});

// ══ DUNIA TUKUK-OS — three new clusters built on keyless APIs: /wang (ECB via
// frankfurter.dev), /seni (The Metropolitan Museum), /hidupan (iNaturalist).
// English for a global audience; the full chrome + 3 ad units like
// akadDoc, with the per-cluster nav injected so one wrapper looks after three pages.
function worldDoc(o, navHtml) {
  const robots = o.robots || 'index,follow';
  const ld = o.ld || JSON.stringify({
    '@context': 'https://schema.org', '@type': 'CollectionPage', name: o.title,
    description: o.desc, url: o.selfUrl,
    publisher: { '@type': 'Organization', name: 'Tukuk-OS', url: 'https://tukuk.org' },
  }).replace(/</g, '\\u003c');
  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(o.title)}</title>
<meta name="description" content="${escapeHtml(o.desc)}">
<meta name="robots" content="${robots}">
<meta property="og:type" content="website">
<meta property="og:site_name" content="Tukuk-OS">
<meta property="og:title" content="${escapeHtml(o.title)}">
<meta property="og:description" content="${escapeHtml(o.desc)}">
<meta property="og:url" content="${o.selfUrl}">
<meta property="og:image" content="${o.ogImage || 'https://tukuk.org/og.png'}">
<meta name="twitter:card" content="summary_large_image">
<link rel="canonical" href="${o.selfUrl}">
<meta name="google-adsense-account" content="ca-pub-8954948214333501">
<script type="application/ld+json">${ld}</script>
<link rel="icon" href="/favicon.ico" sizes="48x48">
<link rel="icon" type="image/svg+xml" href="/icon.svg">
<link rel="apple-touch-icon" href="/apple-touch-icon.png">
<meta name="theme-color" content="#4c8dff">${o.head || ''}
<style>${COMMON_CSS}
.world-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px;margin:18px 0}
.world-card{border:1px solid var(--line);border-radius:10px;padding:16px 18px;background:var(--panel,#171a21);margin:0}
.world-card h3{margin:0 0 8px;font-size:1.05rem}
.world-card p{margin:6px 0;font-size:.95rem}
.world-pill{display:inline-block;border-radius:999px;padding:3px 12px;font-size:.85rem;font-weight:700;color:#fff}
.world-table{width:100%;border-collapse:collapse;margin:16px 0;font-size:.95rem}
.world-table th,.world-table td{border:1px solid var(--line);padding:8px 10px;text-align:left}
.world-table th{background:var(--panel,#171a21)}
.wang-result{border:1px solid var(--line);border-left:4px solid var(--accent,#4c8dff);border-radius:10px;padding:16px 20px;margin:20px 0;background:var(--panel,#171a21)}
.wang-result .big{font-size:1.7rem;font-weight:800;margin:4px 0}
.wang-form{display:flex;gap:10px;flex-wrap:wrap;align-items:flex-end;margin:16px 0}
.wang-form label{display:flex;flex-direction:column;gap:4px;font-size:.85rem;color:var(--muted,#9aa3b2)}
.wang-form select,.wang-form input{padding:8px 10px;border:1px solid var(--line);border-radius:8px;background:var(--bg,#0f1115);color:var(--text,#e6e9ef);font:inherit}
.seni-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:18px 0}
.seni-grid figure{margin:0;border:1px solid var(--line);border-radius:10px;overflow:hidden;background:var(--panel,#171a21)}
.seni-grid img{width:100%;height:180px;object-fit:cover;display:block}
.seni-grid figcaption{padding:9px 11px;font-size:.84rem;line-height:1.4}
@media(max-width:900px){.seni-grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:680px){.world-grid{grid-template-columns:1fr}.seni-grid{grid-template-columns:1fr}}
${o.css || ''}
</style>
<script src="/theme.js"></script>
<link rel="stylesheet" href="/theme.css">
${pageAdScript()}${clarityScript()}
</head>
<body>
${siteHeader('learn')}
<div class="wrap">
  <header><h1>${o.heroHtml || escapeHtml(o.heroTitle || o.title)}</h1><p class="tagline">${escapeHtml(o.heroSub || '')}</p></header>
  <main>${adUnitGuarded(config.adsense.slotTop, 'top')}${msAdUnit('top')}
    ${o.body}
    ${adUnitGuarded(config.adsense.slotInArticle, 'in-article')}${msAdUnit('in-article')}
    ${navHtml}
    ${adUnitGuarded(config.adsense.slotBottom, 'bottom')}${msAdUnit('bottom')}
  </main>
</div>
${siteFooter()}
</body>
</html>`;
}

// A small nav card for every cluster — a card feed like akadNav.
function worldNav(label, items) {
  return `<nav aria-label="${escapeHtml(label)}"><h2 class="section-title">${escapeHtml(label)}</h2><div class="feed">`
    + items.map((s) => `<div class="post-card"><h2><a href="${s.href}">${s.icon} ${escapeHtml(s.name)}</a></h2><p>${escapeHtml(s.blurb)}</p></div>`).join('')
    + `</div></nav>`;
}
const wangNav = () => worldNav('World Money — tukuk.org/wang', [
  { href: '/wang', icon: '💱', name: 'Currency converter', blurb: 'Convert any of 30 world currencies at the latest European Central Bank reference rates — free, no account.' },
  { href: '/wang/kadar', icon: '📊', name: 'All rates today', blurb: 'Every rate the ECB publishes, on one page, refreshed each weekday around 16:00 CET.' },
  { href: '/wang/tukar/USD/EUR', icon: '🇺🇸', name: 'US Dollar → Euro', blurb: 'Live USD/EUR reference rate with a ready amount table and the reverse rate in one glance.' },
  { href: '/wang/tukar/USD/MYR', icon: '🇲🇾', name: 'US Dollar → Ringgit', blurb: 'Live USD/MYR reference rate — the number travellers from Malaysia check most.' },
  { href: '/wang/tukar/USD/INR', icon: '🇮🇳', name: 'US Dollar → Rupee', blurb: 'Live USD/INR reference rate with a ready amount table from ₹100 to ₹1,00,000.' },
  { href: '/wang/tukar/GBP/JPY', icon: '🇬🇧', name: 'Pound → Yen', blurb: 'Cross-rate example: GBP to JPY computed from the same ECB table.' },
]);
const seniNav = () => worldNav('Art Gallery — free images from The Met', [{ href: '/seni', icon: '🖼️', name: 'All collections', blurb: 'Ten curated doors into the Metropolitan Museum’s open-access archive — hundreds of thousands of public-domain images.' }]
  .concat(seni.COLLECTIONS.map((c) => ({ href: `/seni/koleksi/${c.slug}`, icon: c.icon, name: c.name, blurb: c.blurb }))));
const hidupNav = () => worldNav('Wildlife Atlas — real photographs', [{ href: '/hidupan', icon: '🦁', name: 'All species', blurb: 'Sixteen animals, each with a plain-language story and real research-grade photographs from the iNaturalist community.' }
  ].concat(hidup.TAXA.map((t) => ({ href: `/hidupan/${t.slug}`, icon: t.icon, name: t.name, blurb: t.blurb }))));

// ── /unsur — periodic table of the elements (STATIK data embedded) ────────────
const EL_CSS = `.el-scroll{overflow-x:auto;padding-bottom:8px;margin:14px 0}
.el-grid{display:grid;grid-template-columns:repeat(18,minmax(38px,1fr));grid-auto-rows:minmax(44px,auto);gap:3px;min-width:760px}
.el-tile{display:flex;flex-direction:column;justify-content:space-between;text-decoration:none;color:#0b0f16;border-radius:5px;padding:3px 4px;font-size:.7rem;line-height:1.05;background:var(--c);transition:transform .12s}
.el-tile:hover{transform:scale(1.18);z-index:3;box-shadow:0 4px 14px rgba(0,0,0,.4)}
.el-tile .num{opacity:.75;font-size:.6rem}
.el-tile .sym{font-weight:800;font-size:1.05rem}
.el-tile .nm{font-size:.52rem;opacity:.85;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.el-legend{display:flex;flex-wrap:wrap;gap:8px 16px;margin:14px 0;font-size:.82rem}
.el-legend span{display:inline-flex;align-items:center;gap:6px}
.el-legend i{width:14px;height:14px;border-radius:3px;display:inline-block}
.el-hero{display:flex;gap:18px;align-items:center;flex-wrap:wrap}
.el-hero .el-big{display:flex;flex-direction:column;justify-content:center;width:150px;height:150px;border-radius:14px;padding:12px;color:#0b0f16;background:var(--c)}
.el-hero .el-big .b-sym{font-size:3rem;font-weight:800;line-height:1}
.el-hero .el-big .b-nm{font-size:1.1rem;font-weight:700}
.el-hero .el-big .b-meta{display:flex;justify-content:space-between;font-size:.72rem;opacity:.85}`;
const EL_CAT_BLURB = {
  'Reactive nonmetal': 'Elements that readily gain or share electrons — the building blocks of water, air, living tissue and most organic chemistry.',
  'Noble gas': 'Full outer electron shells make these gases almost inert: they barely react, glow in discharge lamps and are used to create unreactive atmospheres.',
  'Alkali metal': 'Soft, wildly reactive metals of group 1 — they fizz in water and never occur pure in nature. Lithium, sodium, potassium and friends.',
  'Alkaline earth metal': 'Reactive group-2 metals a step calmer than the alkalis: magnesium, calcium and the structural and biological workhorses among them.',
  'Transition metal': 'The dense, strong, catalytic heart of the table — iron, copper, gold, titanium — responsible for most of metallurgy, jewellery and industry.',
  'Post-transition metal': 'Softer, lower-melting metals beside the transition block — aluminium, tin, lead — abundant in cans, foils, solders and pigments.',
  'Metalloid': 'In-between elements that behave as semiconductors: silicon, germanium and boron underpin electronics, glass and solar cells.',
  'Lanthanide': 'The rare-earth “inner transition” metals that give strong permanent magnets, screen phosphors and catalyst polish.',
  'Actinide': 'Mostly radioactive, heavy metals — several made only in reactors — whose fission powers nuclear energy and weapons.',
  'Unknown properties': 'Superheavy synthetic elements made atom-by-atom, existing for fractions of a second; their true chemistry is still unmeasured.',
};
const elKelvin = (v) => (v == null ? null : `${v} K (${Math.round(v - 273.15)} °C)`);

function elementsNav() {
  const cats = els.groupedByCategory().map((g) => ({
    href: `/unsur#${els.slugify(g.label)}`, icon: '🧪', name: g.label,
    blurb: `${g.items.length} element${g.items.length > 1 ? 's' : ''}: ${EL_CAT_BLURB[g.label] || 'See the grouping in the periodic table.'}`,
  }));
  return worldNav('Explore by category — Periodic Table /unsur',
    [{ href: '/unsur', icon: '⚛️', name: 'Full periodic table', blurb: 'All 118 chemical elements on one interactive, colour-coded table, each linking to a fact file and plain-language summary.' }].concat(cats));
}

function elementTile(e) {
  return `<a class="el-tile" style="--c:${e.color};grid-column:${e.xpos};grid-row:${e.ypos}" href="/unsur/${e.slug}" title="${escapeHtml(e.name)} — atomic number ${e.n}"><span class="num">${e.n}</span><span class="sym">${escapeHtml(e.s)}</span><span class="nm">${escapeHtml(e.name)}</span></a>`;
}

function elementsHubPage() {
  const grid = els.ELEMENTS.map(elementTile).join('');
  const legend = els.CATEGORY_ORDER.filter((l) => els.CAT_COLOR[l])
    .map((l) => `<span><i style="background:${els.CAT_COLOR[l]}"></i>${l}</span>`).join('');
  const sections = els.groupedByCategory().map((g) => {
    const links = g.items.map((e) => `<a href="/unsur/${e.slug}">${escapeHtml(e.name)} (${escapeHtml(e.s)})</a>`).join(' · ');
    return `<h2 class="section-title" id="${els.slugify(g.label)}">${g.label} <span class="meta">(${g.items.length})</span></h2><p>${escapeHtml(EL_CAT_BLURB[g.label] || '')}</p><p>${links}</p>`;
  }).join('');
  const body = `<p>The <b>periodic table of the elements</b> is chemistry’s map of everything: all 118 known chemical elements, ordered by atomic number and arranged so that elements with similar behaviour fall in the same vertical column. Tap any tile — or pick an element below — for its full fact file, physical properties and a plain-language summary of what it is and what it does.</p>
  <div class="el-scroll"><div class="el-grid">${grid}</div></div>
  <div class="el-legend">${legend}</div>
  <h2 class="section-title">A quick way to read the table</h2><p>Across each <b>period</b> (row) the atomic number climbs by one proton at a time. Down each <b>group</b> (column) the atoms gain a full electron shell, which is why lithium, sodium and potassium all react with water in the same dramatic way. The far-right column is the noble gases — chemically satisfied — while the reactive metals cluster on the left. Elements coloured grey have been made only a few atoms at a time and their properties are still predicted, not measured.</p>
  ${sections}
  <p class="meta">Data: Bowserinator/Periodic-Table-JSON (CC BY-SA 3.0), cross-checked against standard reference values. Kelvin (K) shown with Celsius. Stored statically on our server — no external call when you load a page.</p>`;
  return worldDoc({
    title: 'Periodic Table of Elements — All 118, Interactive with Fact Files | Tukuk-OS',
    desc: 'The complete periodic table of the 118 chemical elements as an interactive, colour-coded grid, each linking to atomic number, mass, melting/boiling points, electron configuration and a plain-language summary.',
    selfUrl: 'https://tukuk.org/unsur',
    heroTitle: '⚛️ The Periodic Table', heroSub: 'All 118 chemical elements · interactive, colour-coded, with fact files',
    css: EL_CSS, body,
  }, elementsNav());
}

function elementPage(req, e) {
  const rows = [
    ['Element category', e.catLabel],
    ['Atomic number', e.n],
    ['Atomic mass', `${e.mass} u`],
    ['Phase at STP', e.phase],
    ['Group', e.group],
    ['Period', e.period],
    ['Block', e.block],
    ['Electron configuration', e.ec],
    ['Electrons per shell', Array.isArray(e.shells) ? e.shells.join(', ') : null],
    ['Electronegativity (Pauling)', e.en],
    ['Melting point', elKelvin(e.melt)],
    ['Boiling point', elKelvin(e.boil)],
    ['Density', e.density != null ? `${e.density} ${e.dunit || 'g/cm³'}` : null],
    ['Discovered by', e.disc],
    ['Named by', e.named],
  ].filter((r) => r[1] != null && String(r[1]).trim()).map((r) => `<tr><th>${escapeHtml(r[0])}</th><td>${escapeHtml(String(r[1]))}</td></tr>`).join('');
  const intro = escapeHtml(e.summ || `${e.name} is a chemical element with symbol ${e.s} and atomic number ${e.n}.`);
  const neighbours = [
    e.n > 1 ? `<a href="/unsur/${(els.ELEMENTS.find((x) => x.n === e.n - 1) || {}).slug}">&larr; ${escapeHtml((els.ELEMENTS.find((x) => x.n === e.n - 1) || {}).name || '')}</a>` : '',
    `<a href="/unsur">Periodic table</a>`,
    e.n < 118 ? `${escapeHtml((els.ELEMENTS.find((x) => x.n === e.n + 1) || {}).name || '')} &rarr; <a href="/unsur/${(els.ELEMENTS.find((x) => x.n === e.n + 1) || {}).slug}">${escapeHtml((els.ELEMENTS.find((x) => x.n === e.n + 1) || {}).s || '')}</a>` : '',
  ].filter(Boolean).join(' · ');
  const body = `<div class="el-hero"><div class="el-big" style="--c:${e.color}"><span class="b-meta"><span>${e.n}</span><span>${e.mass}</span></span><span class="b-sym">${escapeHtml(e.s)}</span><span class="b-nm">${escapeHtml(e.name)}</span><span class="b-meta"><span>${escapeHtml(e.phase || '')}</span><span>${escapeHtml(e.catLabel)}</span></span></div>
  <p>${intro}</p></div>
  <h2 class="section-title">Properties of ${escapeHtml(e.name)}</h2><table class="world-table">${rows}</table>
  <p class="back-link">${neighbours}</p>
  <h2 class="section-title">About the ${escapeHtml(e.catLabel.toLowerCase())} group</h2><p>${escapeHtml(EL_CAT_BLURB[e.catLabel] || '')}</p>
  <p class="meta">Data: Periodic-Table-JSON (CC BY-SA 3.0) · stored statically on our server. ${escapeHtml(e.src || '')}</p>`;
  const ld = JSON.stringify({
    '@context': 'https://schema.org', '@type': 'ChemicalElement', name: e.name, alternateName: e.s,
    url: `https://tukuk.org/unsur/${e.slug}`, description: e.summ || undefined,
    atomicNumber: e.n, molecularFormula: e.s,
    provider: { '@type': 'Organization', name: 'Tukuk-OS', url: 'https://tukuk.org' },
  }).replace(/</g, '\u003c');
  return worldDoc({
    title: `${e.name} (${e.s}) — Properties, Facts & Uses | Periodic Table`,
    desc: `${e.name}, atomic number ${e.n}: symbol, atomic mass, electron configuration, melting and boiling points, density and a plain-language summary of what ${e.name} is used for.`,
    selfUrl: `https://tukuk.org/unsur/${e.slug}`,
    heroTitle: escapeHtml(e.name), heroSub: `${escapeHtml(e.catLabel)} · atomic number ${e.n}`,
    ld, css: EL_CSS, body,
  }, elementsNav());
}

function elementsNotFound(q) {
  return worldDoc({
    title: 'Element not found | Periodic Table — Tukuk-OS',
    desc: 'That element was not recognised — browse the full periodic table of all 118 chemical elements instead.',
    selfUrl: 'https://tukuk.org/unsur', robots: 'noindex,follow',
    heroTitle: 'Element not found', heroSub: `Nothing matched “${escapeHtml(String(q || ''))}”`,
    css: EL_CSS,
    body: `<p>We could not match that to one of the 118 elements. Try a name (e.g. <a href="/unsur/gold">gold</a>), a symbol (e.g. <a href="/unsur/Au">Au</a>) or an atomic number — or open the <a href="/unsur">full periodic table</a> and pick a tile.</p>`,
  }, elementsNav());
}

// ── /buruj + /messier — deep-sky: 88 buruj IAU + 110 objek Messier (STATIK) ──
function deepskyNav() {
  return worldNav('Deep sky — constellations & Messier objects', [
    { href: '/buruj', icon: '✨', name: 'The 88 constellations', blurb: 'Every officially recognised constellation: its Latin name and meaning, brightest star, size on the sky and hemisphere — with the deep-sky objects that lie within each.' },
    { href: '/messier', icon: '🔭', name: 'The 110 Messier objects', blurb: 'The full Messier catalogue of galaxies, nebulae and star clusters — the fuzzy things that kept Charles Messier from finding comets — grouped by type and mapped to their constellation.' },
  ]);
}
const byName = (a, b) => a.name.localeCompare(b.name);

function burujHubPage() {
  const list = [...sky.CONSTELLATIONS].sort(byName);
  const rows = list.map((c) => `<tr><td><a href="/buruj/${c.slug}"><b>${escapeHtml(c.name)}</b></a></td><td>${escapeHtml(c.abbr)}</td><td>${escapeHtml(c.meaning || '—')}</td><td>${escapeHtml(c.brightest || '—')}${c.brightestMag != null ? ` (${c.brightestMag})` : ''}</td><td>${c.area ? c.area.toLocaleString('en-US') : '—'}</td><td>${escapeHtml(c.hemisphere)}</td></tr>`).join('');
  const body = `<p>Since 1922 the International Astronomical Union has recognised exactly <b>88 constellations</b> — defined regions that tile the whole celestial sphere, so every point in the night sky belongs to one. Their names are Latin, most inherited from Ptolemy’s 2nd-century catalogue; the southern ones were added by early-modern European navigators. Below is every constellation with its official three-letter abbreviation, the <b>meaning</b> of its name, its <b>brightest star</b>, its area on the sky and which hemisphere it favours. Each name links to a full profile with the Messier objects found inside it.</p>
  <table class="world-table"><tr><th>Constellation</th><th>Abbr.</th><th>Meaning</th><th>Brightest star</th><th>Area (sq. deg.)</th><th>Hemisphere</th></tr>${rows}</table>
  <p class="meta">Data: IAU-designated constellations, via English Wikipedia (CC BY-SA 3.0), stored statically on our server — no external call when a page loads.</p>`;
  return worldDoc({
    title: 'The 88 Constellations — Names, Meanings, Brightest Stars | Tukuk-OS',
    desc: 'All 88 IAU-recognised constellations with their Latin meaning, brightest star, sky area and hemisphere, each linked to the Messier objects within it.',
    selfUrl: 'https://tukuk.org/buruj',
    heroTitle: '✨ The 88 Constellations', heroSub: 'Every IAU constellation · name, meaning, brightest star & the deep-sky objects inside',
    body,
  }, deepskyNav());
}

function constellationPage(c) {
  const objs = sky.messierInConstellation(c.name).sort((a, b) => Number(a.id.slice(1)) - Number(b.id.slice(1)));
  const objList = objs.length
    ? `<ul>${objs.map((m) => `<li><a href="/messier/${m.slug}">${escapeHtml(m.id)}</a>${m.name ? ` — ${escapeHtml(m.name)}` : ''} <span class="meta">(${escapeHtml(m.type)}${m.mag != null ? `, mag ${m.mag}` : ''})</span></li>`).join('')}</ul>`
    : `<p class="meta">No Messier-catalogued object lies within this constellation’s borders.</p>`;
  const rows = [
    ['Constellation', c.name],
    ['IAU abbreviation', c.abbr],
    ['Genitive (Latin)', c.genitive],
    ['Meaning', c.meaning],
    ['Brightest star', c.brightest ? `${c.brightest}${c.brightestMag != null ? ` (apparent magnitude ${c.brightestMag})` : ''}` : null],
    ['Area', c.area ? `${c.area.toLocaleString('en-US')} square degrees` : null],
    ['Hemisphere', c.hemisphere],
    ['Messier objects here', objs.length ? `${objs.length}` : null],
  ].filter((r) => r[1] != null && String(r[1]).trim()).map((r) => `<tr><th>${escapeHtml(r[0])}</th><td>${escapeHtml(String(r[1]))}</td></tr>`).join('');
  const body = `<p class="back-link"><a href="/buruj">&larr; All 88 constellations</a></p>
  <p><b>${escapeHtml(c.name)}</b> is one of the 88 modern constellations defined by the International Astronomical Union. Its name is Latin${c.meaning ? `, meaning <em>${escapeHtml(c.meaning)}</em>` : ''}${c.genitive ? `; stars within it are named in the genitive form <em>${escapeHtml(c.genitive)}</em>` : ''}.</p>
  <h2 class="section-title">Facts about ${escapeHtml(c.name)}</h2><table class="world-table">${rows}</table>
  <h2 class="section-title">Deep-sky objects in ${escapeHtml(c.name)}</h2>${objList}
  <p class="meta">Data: IAU-designated constellations & the Messier catalogue, via English Wikipedia (CC BY-SA 3.0) · stored statically.</p>`;
  const ld = JSON.stringify({
    '@context': 'https://schema.org', '@type': 'DefinedTerm', name: c.name,
    description: `${c.name} constellation — IAU abbreviation ${c.abbr}${c.meaning ? `, meaning ${c.meaning}` : ''}.${c.brightest ? ` Brightest star ${c.brightest}.` : ''}`,
    url: `https://tukuk.org/buruj/${c.slug}`, inDefinedTermSet: { '@type': 'DefinedTermSet', name: 'IAU constellations', url: 'https://tukuk.org/buruj' },
  }).replace(/</g, '\u003c');
  return worldDoc({
    title: `${c.name} Constellation — Meaning, Brightest Star & Objects | Tukuk-OS`,
    desc: `${c.name} (${c.abbr})${c.meaning ? `, meaning “${c.meaning}”` : ''}${c.brightest ? `, brightest star ${c.brightest}` : ''}: a full profile plus every Messier object lying in this ${c.hemisphere.toLowerCase()} constellation.`,
    selfUrl: `https://tukuk.org/buruj/${c.slug}`,
    heroTitle: `✨ ${escapeHtml(c.name)}`, heroSub: `${escapeHtml(c.abbr)} · ${escapeHtml(c.meaning || '')} · ${escapeHtml(c.hemisphere)} sky`,
    ld, body,
  }, deepskyNav());
}

function messierHubPage() {
  const sections = sky.TYPES.map((t) => {
    const items = sky.messierByType(t).sort((a, b) => Number(a.id.slice(1)) - Number(b.id.slice(1)));
    if (!items.length) return '';
    const links = items.map((m) => `<a href="/messier/${m.slug}">${escapeHtml(m.id)}</a>${m.name ? ` <span class="meta">${escapeHtml(m.name)}</span>` : ''}`).join(' · ');
    return `<h2 class="section-title">${t}s <span class="meta">(${items.length})</span></h2><p>${escapeHtml(sky.TYPE_INFO[t] || '')}</p><p>${links}</p>`;
  }).join('');
  const body = `<p>In the 1770s the French comet-hunter <b>Charles Messier</b> compiled a list of the fuzzy, comet-like objects that kept interrupting his searches — 110 of them in the final, expanded catalogue. Today they are the <b>Messier objects</b>: the brightest galaxies, nebulae and star clusters in the sky, and the backbone of every amateur astronomer’s “Messier marathon”. Every object is below, grouped by what it actually is, each linked to its own page and its home constellation.</p>
  ${sections}
  <p class="meta">Data: Messier catalogue, via English Wikipedia (CC BY-SA 3.0) · stored statically.</p>`;
  return worldDoc({
    title: 'The Messier Catalogue — All 110 Objects by Type | Tukuk-OS',
    desc: 'The complete catalogue of 110 Messier objects — galaxies, nebulae and star clusters — grouped by type, with magnitudes, constellations and a page for each.',
    selfUrl: 'https://tukuk.org/messier',
    heroTitle: '🔭 The Messier Catalogue', heroSub: '110 deep-sky objects · galaxies, nebulae & star clusters',
    body,
  }, deepskyNav());
}

function messierPage(m) {
  const consLink = m.cSlug ? `<a href="/buruj/${m.cSlug}">${escapeHtml(m.constellation)}</a>` : escapeHtml(m.constellation || '—');
  const rows = [
    ['Catalogue designation', m.id],
    ['Common name', m.name],
    ['Object type', m.type],
    ['Constellation', m.constellation || null],
    ['NGC / IC', m.ngc],
    ['Apparent magnitude', m.mag != null ? String(m.mag) : null],
    ['Distance (approx.)', m.distance != null ? `${m.distance.toLocaleString('en-US')} thousand light-years` : null],
  ].filter((r) => r[1] != null && String(r[1]).trim()).map((r) => `<tr><th>${escapeHtml(r[0])}</th><td>${escapeHtml(String(r[1]))}</td></tr>`).join('');
  const siblings = sky.messierInConstellation(m.constellation).filter((x) => x.id !== m.id).sort((a, b) => Number(a.id.slice(1)) - Number(b.id.slice(1)));
  const siblingHtml = siblings.length
    ? `<p>Other Messier objects in ${escapeHtml(m.constellation)}: ${siblings.map((s) => `<a href="/messier/${s.slug}">${escapeHtml(s.id)}</a>`).join(', ')}.</p>` : '';
  const typeInfo = sky.TYPE_INFO[m.type] || '';
  const body = `<p class="back-link"><a href="/messier">&larr; The full Messier catalogue</a></p>
  <p><b>${escapeHtml(m.id)}${m.name ? `, ${escapeHtml(m.name)}` : ''}</b> is a ${escapeHtml(String(m.type).toLowerCase())} in the constellation ${consLink}${m.mag != null ? `, with an apparent magnitude of about ${m.mag}` : ''}${m.distance != null ? `, roughly ${m.distance.toLocaleString('en-US')} thousand light-years away` : ''}.</p>
  <h2 class="section-title">Data</h2><table class="world-table">${rows}</table>
  <h2 class="section-title">What a ${escapeHtml(String(m.type).toLowerCase())} is</h2><p>${escapeHtml(typeInfo)}</p>
  ${siblingHtml}
  <p class="meta">Data: Messier catalogue & IAU constellations, via English Wikipedia (CC BY-SA 3.0) · stored statically.</p>`;
  const ld = JSON.stringify([
    { '@context': 'https://schema.org', '@type': 'Place', name: `${m.id}${m.name ? ` — ${m.name}` : ''}`, description: `${m.type} in ${m.constellation || 'the night sky'}.`, url: `https://tukuk.org/messier/${m.slug}` },
    { '@context': 'https://schema.org', '@type': 'BreadcrumbList', itemListElement: [
      { '@type': 'ListItem', position: 1, name: 'Deep sky', item: 'https://tukuk.org/buruj' },
      { '@type': 'ListItem', position: 2, name: 'Messier catalogue', item: 'https://tukuk.org/messier' },
      { '@type': 'ListItem', position: 3, name: m.id, item: `https://tukuk.org/messier/${m.slug}` },
    ] },
  ]).replace(/</g, '\u003c');
  return worldDoc({
    title: `${m.id}${m.name ? ` (${m.name})` : ''} — ${m.type} Facts & Location | Tukuk-OS`,
    desc: `${m.id}${m.name ? `, ${m.name},` : ''} a ${String(m.type).toLowerCase()} in ${m.constellation || 'the night sky'}${m.mag != null ? ` (magnitude ${m.mag})` : ''}: type, constellation, catalogue references and what this kind of object is.`,
    selfUrl: `https://tukuk.org/messier/${m.slug}`,
    heroTitle: `🔭 ${escapeHtml(m.id)}${m.name ? ` — ${escapeHtml(m.name)}` : ''}`, heroSub: `${escapeHtml(m.type)} in ${escapeHtml(m.constellation || 'the night sky')}`,
    ld, body,
  }, deepskyNav());
}

function burujNotFound(q) {
  return worldDoc({
    title: 'Constellation not found | Tukuk-OS',
    desc: 'That constellation was not recognised — browse the full list of all 88 IAU constellations instead.',
    selfUrl: 'https://tukuk.org/buruj', robots: 'noindex,follow',
    heroTitle: 'Constellation not found', heroSub: `Nothing matched “${escapeHtml(String(q || ''))}”`,
    body: `<p>We could not match that to one of the 88 constellations. Open <a href="/buruj">the full list</a>, or explore the <a href="/messier">Messier catalogue</a>.</p>`,
  }, deepskyNav());
}
function messierNotFound(q) {
  return worldDoc({
    title: 'Messier object not found | Tukuk-OS',
    desc: 'That Messier object was not recognised — browse the full catalogue of 110 Messier objects instead.',
    selfUrl: 'https://tukuk.org/messier', robots: 'noindex,follow',
    heroTitle: 'Messier object not found', heroSub: `Nothing matched “${escapeHtml(String(q || ''))}”`,
    body: `<p>Messier catalogued 110 objects (M1 to M110). Try a designation like <a href="/messier/m31">M31</a> — or open <a href="/messier">the full catalogue</a>.</p>`,
  }, deepskyNav());
}

// ── /pepatah — Proverbs of the World (embedded STATIC data, no API) ────────
const PV_CSS = `.prov-card{border:1px solid var(--line);border-left:4px solid var(--accent);border-radius:12px;padding:16px 18px;margin:14px 0;background:var(--panel,#171a21)}
.prov-orig{font-size:1.5rem;font-weight:800;line-height:1.35;margin:0 0 6px}
.prov-tr{font-style:italic;color:var(--muted,#9aa3b2);margin:0 0 8px;font-size:.95rem}
.prov-en{font-size:1.12rem;font-weight:600;margin:0 0 8px}
.prov-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:16px 0}
.prov-country{border:1px solid var(--line);border-radius:10px;padding:12px 14px;background:var(--panel,#171a21)}
.prov-country h3{margin:0 0 4px;font-size:1rem}
@media(max-width:760px){.prov-grid{grid-template-columns:1fr}}`;

function provCard(p, showLink) {
  const tr = p.translit ? `<p class="prov-tr">${escapeHtml(p.translit)}</p>` : '';
  const link = showLink ? `<p class="meta"><a href="/pepatah/${p.slug}">${escapeHtml(p.lang)} · ${escapeHtml(p.country)}</a></p>` : '';
  return `<div class="prov-card"><p class="prov-orig">${escapeHtml(p.text)}</p>${tr}<p class="prov-en">&ldquo;${escapeHtml(p.en)}&rdquo;</p><p>${escapeHtml(p.meaning)}</p>${link}</div>`;
}
function countryTile(c) {
  return `<div class="prov-country"><h3><a href="/pepatah/negara/${c.slug}">${escapeHtml(c.name)}</a></h3><p class="meta">${c.items.length} proverb${c.items.length > 1 ? 's' : ''} · <a href="/negara/${c.slug}">country profile</a></p></div>`;
}
function pepatahNav() {
  return worldNav('Proverbs of the World — tukuk.org/pepatah', [{ href: '/pepatah', icon: '🗣️', name: 'All proverbs', blurb: 'Traditional sayings from around the world, each with its original wording, a romanisation, a plain-English translation and what it really means.' }
  ].concat(pv.REGION_ORDER.map((r) => ({ href: `/pepatah#${pv.slugify(r)}`, icon: '🌍', name: `${r} proverbs`, blurb: `Folk wisdom from ${pv.countriesInRegion(r).length} ${r} countries in the collection.`}))));
}

function pepatahHubPage() {
  const featured = [pv.findProverb('japan-ishi-no-ue'), pv.findProverb('south-africa-ubuntu'), pv.findProverb('egypt-friend-need')].filter(Boolean).map((p) => provCard(p, true)).join('');
  const sections = pv.REGION_ORDER.map((r) => {
    const cs = pv.countriesInRegion(r);
    if (!cs.length) return '';
    return `<h2 class="section-title" id="${pv.slugify(r)}">${r} <span class="meta">(${cs.reduce((s, c) => s + c.items.length, 0)} proverbs from ${cs.length} countries)</span></h2><div class="prov-grid">${cs.map(countryTile).join('')}</div>`;
  }).join('');
  const body = `<p>A <b>proverb</b> is a short, traditional saying that packs a piece of practical wisdom into a single line — passed down by word of mouth long before it was ever written. Because every culture has learned the same hard lessons about patience, work, friendship and pride, you will often find the <em>same</em> idea phrased in wonderfully different images from Japan to Nigeria. Below are proverbs from ${pv.PROVERBS.length} traditions across ${pv.COUNTRIES.length} countries, each shown in its <b>original language</b> with a romanisation, a plain-English translation and a note on what it actually means. Pick a country to read its sayings together, or follow any line to its own page.</p>
  <h2 class="section-title">A taste from the collection</h2>${featured}
  <h2 class="section-title">Browse by region</h2>${sections}
  <p class="meta">Each country links to its full profile in our World Countries series. Proverbs are traditional folk heritage (public domain); translations and explanations are our own plain-English renderings. Stored statically on our server — no external call when a page loads.</p>`;
  return worldDoc({
    title: 'Proverbs of the World — Traditional Sayings with Meanings | Tukuk-OS',
    desc: `Sixty-five proverbs from ${pv.COUNTRIES.length} countries across every inhabited continent, each with its original wording, romanisation, plain-English translation and the wisdom behind it.`,
    selfUrl: 'https://tukuk.org/pepatah',
    heroTitle: '🗣️ Proverbs of the World', heroSub: `${pv.PROVERBS.length} traditional sayings · ${pv.COUNTRIES.length} countries · original text, translation & meaning`,
    css: PV_CSS, body,
  }, pepatahNav());
}

function pepatahCountryPage(c) {
  const list = c.items.map((p) => provCard(p, true)).join('');
  const siblings = pv.countriesInRegion(c.region).filter((x) => x.slug !== c.slug);
  const otherLinks = siblings.length ? `<h2 class="section-title">More ${escapeHtml(c.region)} proverbs</h2><p>${siblings.map((x) => `<a href="/pepatah/negara/${x.slug}">${escapeHtml(x.name)}</a>`).join(' · ')}.</p>` : '';
  const body = `<p class="back-link"><a href="/pepatah">&larr; All proverbs</a></p>
  <p><b>${escapeHtml(c.name)}</b> contributes ${c.items.length} proverb${c.items.length > 1 ? 's' : ''} to this collection. A country&rsquo;s sayings reveal what its people prize most. See the full <a href="/negara/${c.slug}">profile of ${escapeHtml(c.name)}</a> for its geography, languages and history.</p>
  ${list}
  ${otherLinks}
  <p class="meta">Proverbs are traditional folk heritage (public domain); translations and meanings are plain-English renderings. Stored statically.</p>`;
  const ld = JSON.stringify({
    '@context': 'https://schema.org', '@type': 'CollectionPage', name: `Proverbs of ${c.name}`, description: `${c.items.length} traditional proverbs from ${c.name} with English translations and meanings.`, url: `https://tukuk.org/pepatah/negara/${c.slug}`,
    mainEntity: { '@type': 'ItemList', itemListElement: c.items.map((p, i) => ({ '@type': 'ListItem', position: i + 1, name: p.en, url: `https://tukuk.org/pepatah/${p.slug}` })) },
  }).replace(/</g, '\u003c');
  return worldDoc({
    title: `Proverbs of ${c.name} — Sayings & Meanings | Tukuk-OS`,
    desc: `${c.items.length} traditional ${c.name} proverbs with their original wording, English translations and the wisdom behind each — from the Proverbs of the World collection.`,
    selfUrl: `https://tukuk.org/pepatah/negara/${c.slug}`,
    heroTitle: `🗣️ Proverbs of ${escapeHtml(c.name)}`, heroSub: `${escapeHtml(c.region)} · ${c.items.length} traditional sayings`,
    ld, css: PV_CSS, body,
  }, pepatahNav());
}

function pepatahProverbPage(p) {
  const others = pv.findCountry(p.countrySlug).items.filter((x) => x.slug !== p.slug);
  const moreList = others.length ? `<h2 class="section-title">More proverbs from ${escapeHtml(p.country)}</h2>${others.map((x) => provCard(x, false)).join('')}` : '';
  const tr = p.translit ? `<tr><th>Romanisation</th><td>${escapeHtml(p.translit)}</td></tr>` : '';
  const rows = [
    ['Origin country', `<a href="/negara/${p.countrySlug}">${escapeHtml(p.country)}</a>`],
    ['Region', escapeHtml(p.region)],
    ['Language', escapeHtml(p.lang)],
  ].map((r) => `<tr><th>${r[0]}</th><td>${r[1]}</td></tr>`).join('') + tr;
  const body = `<p class="back-link"><a href="/pepatah">&larr; All proverbs</a> · <a href="/pepatah/negara/${p.countrySlug}">${escapeHtml(p.country)} proverbs</a></p>
  <div class="prov-card"><p class="prov-orig">${escapeHtml(p.text)}</p>${p.translit ? `<p class="prov-tr">${escapeHtml(p.translit)}</p>` : ''}<p class="prov-en">&ldquo;${escapeHtml(p.en)}&rdquo;</p><p>${escapeHtml(p.meaning)}</p></div>
  <h2 class="section-title">About this proverb</h2><table class="world-table">${rows}</table>
  <p>This saying belongs to the oral tradition of <a href="/negara/${p.countrySlug}">${escapeHtml(p.country)}</a>, a country in ${escapeHtml(p.region)}. Read the full <a href="/pepatah/negara/${p.countrySlug}">collection of ${escapeHtml(p.country)} proverbs</a>, or explore the <a href="/pepatah">Proverbs of the World</a> index.</p>
  ${moreList}
  <p class="meta">Proverbs are traditional folk heritage (public domain); the translation and explanation are our own plain-English rendering. Stored statically.</p>`;
  const ld = JSON.stringify([
    { '@context': 'https://schema.org', '@type': 'Quotation', text: p.text, inLanguage: p.lang, url: `https://tukuk.org/pepatah/${p.slug}`, attribution: `${p.country} folk tradition`, creator: { '@type': 'Organization', name: `${p.lang} oral tradition` } },
    { '@context': 'https://schema.org', '@type': 'BreadcrumbList', itemListElement: [
      { '@type': 'ListItem', position: 1, name: 'Proverbs of the World', item: 'https://tukuk.org/pepatah' },
      { '@type': 'ListItem', position: 2, name: p.country, item: `https://tukuk.org/pepatah/negara/${p.countrySlug}` },
      { '@type': 'ListItem', position: 3, name: p.en, item: `https://tukuk.org/pepatah/${p.slug}` },
    ] },
  ]).replace(/</g, '\u003c');
  return worldDoc({
    title: `${p.en} — ${p.lang} Proverb (${p.country}) | Tukuk-OS`,
    desc: `The ${p.country} proverb ${p.translit ? `(${p.translit}) ` : ''}“${p.en}” — its original wording, English translation and the practical wisdom behind it.`,
    selfUrl: `https://tukuk.org/pepatah/${p.slug}`,
    heroTitle: `🗣️ ${escapeHtml(p.country)}: &ldquo;${escapeHtml(p.en)}&rdquo;`, heroSub: `${escapeHtml(p.lang)} proverb · ${escapeHtml(p.region)}`,
    ld, css: PV_CSS, body,
  }, pepatahNav());
}

function pepatahNotFound(q) {
  return worldDoc({
    title: 'Proverb not found | Proverbs of the World — Tukuk-OS',
    desc: 'That proverb was not recognised — browse the full collection of world proverbs instead.',
    selfUrl: 'https://tukuk.org/pepatah', robots: 'noindex,follow',
    heroTitle: 'Proverb not found', heroSub: `Nothing matched “${escapeHtml(String(q || ''))}”`,
    css: PV_CSS,
    body: `<p>We could not match that to one of our world proverbs. Open <a href="/pepatah">the full collection</a> and browse by country or region.</p>`,
  }, pepatahNav());
}

// ── /rekod — World Extremes (superlatives of the Earth, STATIC embedded data) ──
const REC_CSS = `.rek-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin:16px 0}
.rek-card{display:block;border:1px solid var(--line);border-left:4px solid var(--accent,#4c8dff);border-radius:10px;padding:13px 16px;background:var(--panel,#171a21);text-decoration:none;color:inherit}
.rek-card h3{margin:0 0 4px;font-size:1.02rem}
.rek-card .rek-name{font-weight:700;color:var(--accent,#4c8dff);margin:2px 0}
.rek-card .rek-val{font-size:.9rem;color:var(--muted,#9aa3b2);margin:2px 0 0}
.rek-cat-title{display:flex;align-items:center;gap:8px}
.rek-lead{text-align:center;margin:22px 0}
.rek-lead .rek-big{font-size:1.9rem;font-weight:800;color:var(--accent,#4c8dff);margin:4px 0}
.rek-lead .rek-sub{color:var(--muted,#9aa3b2)}
@media(max-width:680px){.rek-grid{grid-template-columns:1fr}}`;
const REK_CAT_EMOJI = {
  'Mountains & Peaks': '⛰️', 'Rivers & Canals': '🏞️', 'Lakes & Inland Water': '💧',
  'Oceans & Seas': '🌊', 'Waterfalls': '💦', 'Caves & Canyons': '🕳️',
  'Deserts & Drylands': '🏜️', 'Ice & Cold': '❄️', 'Islands & Coasts': '🏝️',
  'The Built World': '🏗️', 'Weather & Climate': '🌡️',
};
const REK_CLUSTER_LABEL = {
  gunung: 'Mountains', 'gunung-berapi': 'Volcanoes', sungai: 'Rivers', terusan: 'Canals',
  danau: 'Lakes', laut: 'Seas & Oceans', 'oceanic-trenches': 'Ocean Trenches', teluk: 'Bays',
  'air-terjun': 'Waterfalls', gua: 'Caves', ngarai: 'Canyons & Gorges', gurun: 'Deserts',
  gletser: 'Glaciers', pulau: 'Islands', 'terumbu-karang': 'Coral Reefs', 'pencakar-langit': 'Skyscrapers',
  jambatan: 'Bridges', terowong: 'Tunnels', 'suspension-bridges': 'Suspension Bridges', 'city-walls': 'Walls & Fortifications',
  patung: 'Statues', stadium: 'Stadiums', 'metro-stations': 'Metro Stations', 'lapangan-terbang': 'Airports',
};

function rekCard(r) {
  return `<a class="rek-card" href="/rekod/${r.slug}"><h3>${escapeHtml(r.record)}</h3><p class="rek-name">${escapeHtml(r.name)}</p><p class="rek-val">${escapeHtml(r.value)} &middot; ${escapeHtml(r.place)}</p></a>`;
}

function rekodNav() {
  return worldNav('World Extremes — tukuk.org/rekod', [{ href: '/rekod', icon: '📏', name: 'Every record, one page', blurb: 'The highest, longest, deepest, largest and driest places on Earth — natural wonders and human-built superlatives, each on its own fact page.' }
  ].concat(rek.CATEGORIES.map((c) => ({ href: `/rekod#${c.slug}`, icon: REK_CAT_EMOJI[c.name] || '📏', name: c.name, blurb: `${c.items.length} world records in this category, from extremes of the natural world to the tallest things people have built.`}))));
}

function rekodHubPage() {
  const toc = rek.CATEGORIES.map((c) => `<a href="/rekod#${c.slug}">${REK_CAT_EMOJI[c.name] || '📏'} ${escapeHtml(c.name)} (${c.items.length})</a>`).join(' · ');
  const sections = rek.CATEGORIES.map((c) => {
    const cards = c.items.map(rekCard).join('');
    return `<h2 class="section-title rek-cat-title" id="${c.slug}">${REK_CAT_EMOJI[c.name] || '📏'} ${escapeHtml(c.name)} <span class="meta">(${c.items.length} records)</span></h2><div class="rek-grid">${cards}</div>`;
  }).join('');
  const body = `<p>Our <b>World Extremes</b> collection gathers the superlatives of the planet — the <em>highest</em> mountain, the <em>longest</em> river, the <em>deepest</em> ocean trench, the <em>driest</em> desert, the <em>tallest</em> building and dozens more. Every entry is a single record with a plain measurement, where it is, and one or two sentences explaining it. Because these facts are settled, each page is stored statically on our server, so it loads instantly and never fails. Open any record for its full fact file and links to the country and the collection it belongs to.</p>
  <h2 class="section-title">Browse by category</h2><p>${toc}</p>
  ${sections}
  <p class="meta">Figures are the widely-cited reference measurements; a few records (river length, mountain height) are refined as surveying improves. Stored statically on our server — no external call when you load a page. Explore more world knowledge: <a href="/gunung">mountains</a>, <a href="/sungai">rivers</a>, <a href="/danau">lakes</a>, <a href="/warisan">world heritage</a>, <a href="/negara">countries</a>.</p>`;
  return worldDoc({
    title: 'World Extremes — the Highest, Longest, Deepest & Largest on Earth | Tukuk-OS',
    desc: `${rek.RECORDS.length} world records in one place: the highest mountain, longest river, deepest trench, largest desert, tallest building and more, each with its measurement, location and a plain-English explanation.`,
    selfUrl: 'https://tukuk.org/rekod',
    heroTitle: '📏 World Extremes', heroSub: `${rek.RECORDS.length} superlatives of the Earth · natural wonders & human-built records`,
    css: REC_CSS, body,
  }, rekodNav());
}

function rekodRecordPage(r) {
  const catEmoji = REK_CAT_EMOJI[r.category] || '📏';
  const rows = [
    ['Record', escapeHtml(r.record)],
    ['Feature', escapeHtml(r.name)],
    ['Measurement', escapeHtml(r.value)],
    ['Location', escapeHtml(r.place)],
    r.country ? ['Country', `<a href="/negara/${r.countrySlug}">${escapeHtml(r.country)}</a>`] : null,
  ].filter(Boolean).map((x) => `<tr><th>${x[0]}</th><td>${x[1]}</td></tr>`).join('');
  const clusterLink = r.cluster
    ? `<p class="meta">This record belongs to our <a href="/${r.cluster}">${REK_CLUSTER_LABEL[r.cluster] || escapeHtml(r.cluster)}</a> collection, where every ${REK_CLUSTER_LABEL[r.cluster] ? REK_CLUSTER_LABEL[r.cluster].toLowerCase() : r.cluster} in the world is catalogued.</p>`
    : '';
  const readLine = r.country
    ? `Read the <a href="/negara/${r.countrySlug}">${escapeHtml(r.country)}</a> profile, or browse the whole <a href="/rekod">World Extremes</a> index.`
    : `Browse the whole <a href="/rekod">World Extremes</a> index for more records like this one.`;
  const siblings = rek.recordsInCategory(r.category).filter((x) => x.slug !== r.slug);
  const moreBlock = siblings.length
    ? `<h2 class="section-title">More ${escapeHtml(r.category)} records</h2><div class="rek-grid">${siblings.map(rekCard).join('')}</div>`
    : '';
  const body = `<p class="back-link"><a href="/rekod">&larr; All world records</a> · <a href="/rekod#${r.catSlug}">${escapeHtml(r.category)}</a></p>
  <div class="rek-lead"><h2 class="section-title" style="text-align:center">${catEmoji} ${escapeHtml(r.record)}</h2><p class="rek-big">${escapeHtml(r.value)}</p><p class="rek-sub">${escapeHtml(r.name)} &middot; ${escapeHtml(r.place)}</p></div>
  <p>${escapeHtml(r.blurb)}</p>
  <h2 class="section-title">Record at a glance</h2><table class="world-table">${rows}</table>
  <p>${readLine}</p>
  ${clusterLink}
  ${moreBlock}
  <p class="meta">Figure is a widely-cited reference measurement. Stored statically on our server — no external call when you load a page.</p>`;
  const ld = JSON.stringify([
    { '@context': 'https://schema.org', '@type': 'CreativeWork', name: r.record, headline: `${r.record}: ${r.name}`, description: r.blurb, url: `https://tukuk.org/rekod/${r.slug}`, keywords: r.category },
    { '@context': 'https://schema.org', '@type': 'BreadcrumbList', itemListElement: [
      { '@type': 'ListItem', position: 1, name: 'World Extremes', item: 'https://tukuk.org/rekod' },
      { '@type': 'ListItem', position: 2, name: r.category, item: `https://tukuk.org/rekod#${r.catSlug}` },
      { '@type': 'ListItem', position: 3, name: r.record, item: `https://tukuk.org/rekod/${r.slug}` },
    ] },
  ]).replace(/</g, '\u003c');
  return worldDoc({
    title: `${r.record} — ${r.name} (${r.value}) | World Extremes`,
    desc: `${r.record}: ${r.name} at ${r.value}, in ${r.place}. Measurement, location and a plain-English explanation from the tukuk.org World Extremes collection.`,
    selfUrl: `https://tukuk.org/rekod/${r.slug}`,
    heroTitle: `${catEmoji} ${escapeHtml(r.record)}`, heroSub: `${escapeHtml(r.name)} · ${escapeHtml(r.value)}`,
    ld, css: REC_CSS, body,
  }, rekodNav());
}

function rekodNotFound(q) {
  return worldDoc({
    title: 'Record not found | World Extremes — Tukuk-OS',
    desc: 'That record was not recognised — browse the full World Extremes collection instead.',
    selfUrl: 'https://tukuk.org/rekod', robots: 'noindex,follow',
    heroTitle: 'Record not found', heroSub: `Nothing matched “${escapeHtml(String(q || ''))}”`,
    css: REC_CSS,
    body: `<p>We could not match that to one of our world records. Open <a href="/rekod">the full World Extremes collection</a> and browse by category.</p>`,
  }, rekodNav());
}

// ── /traffic — Tukuk Traffic (Waze-style community road reports) ───────────────
// One Leaflet map + a sidebar list; the whole UI lives in ONE inline <script> so
// the page is a single round-trip and works offline once the shell is cached.
// All data changes flow through the three /api/traffic/* JSON endpoints above.
const TRAFFIC_CSS = `#trf-wrap{display:grid;grid-template-columns:1fr 340px;gap:14px;margin:18px 0}
@media(max-width:900px){#trf-wrap{grid-template-columns:1fr}}
#trf-map{height:520px;border:1px solid var(--line);border-radius:12px;background:var(--panel,#171a21);z-index:1}
#trf-side{border:1px solid var(--line);border-radius:12px;background:var(--panel,#171a21);padding:14px;max-height:520px;overflow-y:auto}
#trf-side h3{margin:0 0 10px;font-size:.95rem;color:var(--muted,#9aa3b2);text-transform:uppercase;letter-spacing:.5px}
.trf-row{border-bottom:1px solid var(--line);padding:9px 0;font-size:.92rem;line-height:1.4}
.trf-row:last-child{border-bottom:none}
.trf-row .t{display:flex;align-items:center;gap:8px;margin-bottom:3px}
.trf-row .t b{font-weight:600}
.trf-row .m{color:var(--muted,#9aa3b2);font-size:.78rem}
.trf-row .n{margin:4px 0 0}
.trf-v{display:inline-flex;gap:6px;margin-top:4px}
.trf-v button{background:var(--bg,#0f1115);border:1px solid var(--line);border-radius:6px;padding:2px 8px;color:inherit;font:inherit;font-size:.78rem;cursor:pointer}
.trf-v button:hover{border-color:var(--accent,#4c8dff)}
.trf-v button[disabled]{opacity:.4;cursor:default}
.trf-chip{display:inline-flex;align-items:center;gap:5px;padding:5px 10px;border-radius:999px;background:var(--panel,#171a21);border:1px solid var(--line);font-size:.82rem;cursor:pointer;user-select:none;margin:0 4px 6px 0}
.trf-chip.on{border-color:var(--accent,#4c8dff);background:color-mix(in srgb,var(--accent) 15%,transparent);color:var(--text)}
.trf-chip .dot{width:10px;height:10px;border-radius:50%;display:inline-block}
#trf-form{margin:16px 0;padding:14px;border:1px solid var(--line);border-radius:12px;background:var(--panel,#171a21);display:none}
#trf-form.show{display:block}
#trf-form input,#trf-form textarea{width:100%;padding:8px 10px;border:1px solid var(--line);border-radius:8px;background:var(--bg,#0f1115);color:var(--text,#e6e9ef);font:inherit;box-sizing:border-box}
#trf-form textarea{min-height:60px;resize:vertical}
#trf-form .lbl{font-size:.82rem;color:var(--muted,#9aa3b2);margin:8px 0 4px}
#trf-form .coord{font-family:monospace;font-size:.85rem;color:var(--accent,#4c8dff)}
.trf-fabs{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}
.trf-btn{padding:8px 14px;border-radius:10px;border:1px solid var(--line);background:var(--panel,#171a21);color:var(--text);font:inherit;font-weight:600;cursor:pointer}
.trf-btn:hover{border-color:var(--accent,#4c8dff);text-decoration:none}
.trf-btn.primary{background:var(--accent,#4c8dff);color:#fff;border-color:transparent}
.trf-btn.primary:hover{filter:brightness(1.1)}
.trf-btn[disabled]{opacity:.5;cursor:default}
#trf-status{font-size:.85rem;color:var(--muted,#9aa3b2);margin-left:6px}
.leaflet-popup-content{font:15px/1.55 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;color:#151922}
.leaflet-popup-content b{color:#0b0f16}`;

function trafficHubPage() {
  const activeCount = trf.activeCount();
  const counts = trf.countsByType();
  const initialReports = JSON.stringify(trf.listActive()).replace(/</g, '\\u003c');
  const typeMeta = JSON.stringify(trf.TYPES).replace(/</g, '\\u003c');
  // The chips row is server-rendered for SEO (the map itself is JS-only), so a
  // crawler sees at least a summary of what types exist and the current counts.
  const chipsHtml = Object.entries(trf.TYPES).map(([key, t]) =>
    `<span class="trf-chip" data-type="${key}"><span class="dot" style="background:${t.color}"></span>${escapeHtml(t.emoji + ' ' + t.label)} <b class="meta">(${counts[key] || 0})</b></span>`
  ).join('');
  const listHtml = trf.listActive().slice(0, 20).map((r) =>
    `<div class="trf-row" data-id="${r.id}"><div class="t"><span>${r.emoji}</span><b>${escapeHtml(r.label)}</b><span class="m">· ${r.expiresInMin} min left</span></div><p class="n">${escapeHtml(r.note || '(no details)')}</p><p class="m">▲ ${r.up} · ▼ ${r.down}</p></div>`
  ).join('') || '<p class="meta">No reports yet — be the first to add one.</p>';
  const body = `<p><b>Tukuk Traffic</b> is a small, community-run road board: anyone can drop a pin for a jam, an accident, a police checkpoint, a hazard, a road closure, a speed camera, heavy rain or a fuel-price tip. Reports <b>fade out automatically</b> as they age (traffic in an hour, closures in a day, cameras in a week), and every driver can up-vote what they still see or down-vote what has cleared — so the map shows <em>the road right now</em>, not a stale archive. There is no login, no account and no location tracking: it is a shared whiteboard for anyone on the road.</p>
  <div class="trf-fabs">
    <button class="trf-btn primary" id="trf-new">➕ New report</button>
    <button class="trf-btn" id="trf-me">🎯 Near me</button>
    <button class="trf-btn" id="trf-refresh">🔄 Refresh</button>
    <span id="trf-status">${activeCount} active reports worldwide · auto-refresh every 30s</span>
  </div>
  <div id="trf-filters">${chipsHtml}</div>
  <div id="trf-form">
    <p class="lbl">1. <b>Tap anywhere on the map</b> to place your pin — or use “Near me” above. Current pin: <span class="coord" id="trf-pin">no pin yet</span></p>
    <p class="lbl">2. Choose what you are reporting:</p>
    <div id="trf-types">${Object.entries(trf.TYPES).map(([k, t]) => `<button type="button" class="trf-btn trf-type" data-type="${k}" style="margin:2px 4px 4px 0"><span class="dot" style="display:inline-block;width:9px;height:9px;border-radius:50%;background:${t.color};vertical-align:middle;margin-right:5px"></span>${escapeHtml(t.emoji + ' ' + t.label)}</button>`).join('')}</div>
    <p class="lbl">3. Optional details (max 140 characters):</p>
    <textarea id="trf-note" maxlength="140" placeholder="e.g. two lanes blocked on the north approach, expect 15 min delay"></textarea>
    <p class="lbl" id="trf-form-msg" style="min-height:1.2em"></p>
    <p><button class="trf-btn primary" id="trf-submit" disabled>Submit report</button> <button class="trf-btn" id="trf-cancel" type="button">Cancel</button></p>
  </div>
  <div id="trf-wrap">
    <div id="trf-map" role="application" aria-label="Live road-report map"></div>
    <aside id="trf-side"><h3>Latest reports</h3><div id="trf-list">${listHtml}</div></aside>
  </div>
  <noscript><p>JavaScript is required for the interactive map. Reload with JS enabled, or browse the <a href="/cuaca">world weather</a> instead.</p></noscript>
  <h2 class="section-title">How the community keeps it honest</h2>
  <p>Every report has a <b>time-to-live</b>: a traffic-jam report naturally clears within an hour, police checkpoints within three, closures stay posted for a full day, and speed cameras — being fixed objects — persist for a week. The clock starts the moment you post. Up-votes from other drivers extend the clock a little (up to ten extra minutes per vote, capped at six votes’ worth), and once a report has five more down-votes than up-votes it disappears immediately. That way we never need a human moderator: the crowd trims the board by itself.</p>
  <h2 class="section-title">What this is not</h2>
  <p>Tukuk Traffic is <b>not a turn-by-turn navigation app</b> and we do not offer live GPS routing or ETA prediction. It is a plain community notice board with a map on it. Nothing here is verified by authorities — use it as a heads-up alongside your own judgement and always obey local traffic laws. Want point-to-point directions instead? Open <a href="/peta">Maps &amp; Navigation</a>.</p>
  <h2 class="section-title">Data &amp; privacy</h2>
  <p>Reports are anonymous. We do not attach any user ID, IP address or device fingerprint to a post. Coordinates are rounded to 5 decimal places (roughly a metre), and we keep at most 500 active reports on the server at any time. Old rows are removed automatically on every read and every write.</p>
  <p class="meta">Base map: © <a href="https://www.openstreetmap.org/copyright" rel="noopener nofollow">OpenStreetMap</a> contributors, rendered with Leaflet. Data: this site only — stored in <code>data/traffic.json</code>, reloaded atomically.</p>`;
  const script = `<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css">`
    + `<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js" defer></script>`
    + `<script>(function(){var TYPES=${typeMeta};var SEED=${initialReports};var all=SEED.slice();var pin=null;var chosenType=null;var voted={};var markers={};var activeTypes={};Object.keys(TYPES).forEach(function(k){activeTypes[k]=true;});function fmtAgo(ms){var m=Math.max(0,Math.round((Date.now()-ms)/60000));if(m<1)return'moments ago';if(m<60)return m+' min ago';var h=Math.floor(m/60);if(h<24)return h+' hr ago';return Math.floor(h/24)+' d ago';}
function boot(){if(!window.L){setTimeout(boot,300);return;}var m=L.map('trf-map',{zoomControl:true,scrollWheelZoom:true}).setView([20,20],2);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'\\u00a9 OpenStreetMap'}).addTo(m);window.__trfMap=m;render(m);
  m.on('click',function(e){pin=[e.latlng.lat.toFixed(5),e.latlng.lng.toFixed(5)];document.getElementById('trf-pin').textContent=pin.join(', ');showForm();var b=document.getElementById('trf-submit');if(b&&chosenType)b.disabled=false;});}
function showForm(){document.getElementById('trf-form').classList.add('show');}
function hideForm(){document.getElementById('trf-form').classList.remove('show');}
function clearMarkers(){var m=window.__trfMap;Object.keys(markers).forEach(function(id){if(markers[id])m.removeLayer(markers[id]);delete markers[id];});}
function render(m){clearMarkers();var list=document.getElementById('trf-list');if(!list||!m)m=window.__trfMap;var shown=all.filter(function(r){return activeTypes[r.type];});shown.forEach(function(r){var t=TYPES[r.type];if(!t)return;var mk=L.circleMarker([r.lat,r.lon],{radius:9,color:t.color,weight:2,fillColor:t.color,fillOpacity:.55}).addTo(m);mk.bindPopup('<b>'+t.emoji+' '+t.label+'</b><br>'+(r.note||'')+'<br><small>'+fmtAgo(r.createdAt)+' · ▲'+r.up+' ▼'+r.down+' · '+r.expiresInMin+' min left</small><br><button data-vote="up" data-id="'+r.id+'" class="trf-btn" style="padding:2px 8px">👍 still here</button> <button data-vote="down" data-id="'+r.id+'" class="trf-btn" style="padding:2px 8px">👎 cleared</button>');markers[r.id]=mk;});
  list.innerHTML=shown.slice(0,25).map(function(r){var t=TYPES[r.type];return '<div class="trf-row" data-id="'+r.id+'"><div class="t">'+t.emoji+' <b>'+t.label+'</b><span class="m">· '+fmtAgo(r.createdAt)+'</span></div><p class="n">'+((r.note||'').replace(/[&<>]/g,function(c){return({'&':'&amp;','<':'&lt;','>':'&gt;'})[c];}))+'</p><p class="trf-v"><button data-vote="up" data-id="'+r.id+'">▲ '+r.up+'</button><button data-vote="down" data-id="'+r.id+'">▼ '+r.down+'</button><span class="m">· '+r.expiresInMin+' min left</span></p></div>';}).join('')||'<p class="meta">No reports match the current filter.</p>';}
function fetchReports(){return fetch('/api/traffic/reports').then(function(x){return x.json();}).then(function(j){all=j.reports||[];render(window.__trfMap);var s=document.getElementById('trf-status');if(s)s.textContent=all.length+' active reports worldwide · refreshed '+new Date().toLocaleTimeString();}).catch(function(){var s=document.getElementById('trf-status');if(s)s.textContent='could not refresh — will retry';});}
function vote(id,dir){if(voted[id+':'+dir])return;voted[id+':'+dir]=1;fetch('/api/traffic/vote',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:id,dir:dir})}).then(function(x){return x.json();}).then(function(j){if(!j.ok){delete voted[id+':'+dir];return;}for(var i=0;i<all.length;i++){if(all[i].id===id){all[i]=j.report;break;}}render(window.__trfMap);}).catch(function(){delete voted[id+':'+dir];});}
function submit(){if(!pin||!chosenType)return;var note=document.getElementById('trf-note').value||'';var msg=document.getElementById('trf-form-msg');msg.textContent='submitting…';fetch('/api/traffic/report',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({lat:+pin[0],lon:+pin[1],type:chosenType,note:note})}).then(function(x){return x.json();}).then(function(j){if(!j.ok){msg.textContent='⚠ '+j.error;return;}all.unshift(j.report);render(window.__trfMap);msg.textContent='✅ posted — thank you!';pin=null;chosenType=null;document.getElementById('trf-note').value='';document.getElementById('trf-pin').textContent='no pin yet';document.querySelectorAll('.trf-type').forEach(function(b){b.style.outline='';});setTimeout(function(){hideForm();msg.textContent='';},1500);}).catch(function(){msg.textContent='⚠ network error';});}
document.addEventListener('DOMContentLoaded',function(){boot();
  document.getElementById('trf-new').onclick=function(){showForm();};
  document.getElementById('trf-cancel').onclick=function(){hideForm();};
  document.getElementById('trf-refresh').onclick=function(){fetchReports();};
  document.getElementById('trf-me').onclick=function(){if(!navigator.geolocation){alert('Your browser does not expose location.');return;}navigator.geolocation.getCurrentPosition(function(p){var c=[p.coords.latitude,p.coords.longitude];window.__trfMap.setView(c,13);pin=[c[0].toFixed(5),c[1].toFixed(5)];document.getElementById('trf-pin').textContent=pin.join(', ');showForm();document.getElementById('trf-submit').disabled=!chosenType;},function(e){alert('Location denied: '+(e.message||''));});};
  document.getElementById('trf-submit').onclick=submit;
  document.querySelectorAll('.trf-type').forEach(function(b){b.onclick=function(){document.querySelectorAll('.trf-type').forEach(function(x){x.style.outline='';});b.style.outline='2px solid var(--accent)';chosenType=b.dataset.type;if(pin)document.getElementById('trf-submit').disabled=false;};});
  document.querySelectorAll('.trf-chip').forEach(function(c){c.onclick=function(){var k=c.dataset.type;activeTypes[k]=!activeTypes[k];c.classList.toggle('on',!activeTypes[k]?false:true);if(!activeTypes[k])c.classList.add('on');else c.classList.remove('on');render(window.__trfMap);c.classList.toggle('on',!activeTypes[k]);};});
  document.addEventListener('click',function(e){var t=e.target;if(t&&t.dataset&&t.dataset.vote&&t.dataset.id){vote(t.dataset.id,t.dataset.vote);}});
  setInterval(fetchReports,30000);
});})();</script>`;
  return worldDoc({
    title: 'Tukuk Traffic — Community Road Reports, Live Hazards, Police, Closures & Jams | Tukuk-OS',
    desc: 'A free, anonymous, community-maintained road map: report and see traffic jams, accidents, police checkpoints, road hazards, closures, speed cameras, heavy rain and fuel prices in real time — anywhere in the world.',
    selfUrl: 'https://tukuk.org/traffic',
    heroTitle: '🚦 Tukuk Traffic',
    heroSub: 'Community road reports · auto-fading · no login · worldwide',
    css: TRAFFIC_CSS,
    body: body + script,
    ld: JSON.stringify({
      '@context': 'https://schema.org', '@type': 'WebApplication', name: 'Tukuk Traffic',
      applicationCategory: 'NavigationApplication', operatingSystem: 'Web',
      description: 'Community road reports — traffic, accidents, police, hazards, closures, cameras, rain and fuel prices.',
      url: 'https://tukuk.org/traffic', offers: { '@type': 'Offer', price: '0', priceCurrency: 'USD' }
    }).replace(/</g, '\\u003c')
  });
}

function trafficBusy() {
  return `<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,follow"><title>Tukuk Traffic is briefly unavailable | Tukuk-OS</title><body style="font-family:system-ui,Arial,sans-serif;max-width:640px;margin:64px auto;padding:20px;line-height:1.6"><h1>🚦 Tukuk Traffic</h1><p>The traffic board is briefly unavailable while the server reloads. Reports are cached, so please refresh in a moment.</p><p><a href="/">Back to Tukuk-OS</a></p></body></html>`;
}

// ── /teknologi — Technology complex (Hacker News front page via Algolia API) ────
const TK_CSS = `.tk-item{display:flex;gap:14px;border:1px solid var(--line);border-left:4px solid var(--accent,#4c8dff);border-radius:10px;padding:12px 16px;margin:10px 0;background:var(--panel,#171a21)}
.tk-score{min-width:64px;display:flex;flex-direction:column;align-items:center;justify-content:center;font-weight:800;font-size:1.15rem;color:var(--accent,#4c8dff)}
.tk-score span{font-weight:600;font-size:.68rem;color:var(--muted,#9aa3b2);text-transform:uppercase;letter-spacing:.04em}
.tk-main{flex:1;min-width:0}
.tk-main h3{margin:0 0 4px;font-size:1.02rem;line-height:1.35}
.tk-meta{margin:0;font-size:.83rem;color:var(--muted,#9aa3b2)}
.tk-text{margin:6px 0 0;font-size:.9rem}
.tk-topline{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;align-items:center;margin:14px 0;font-size:.9rem}
@media(max-width:560px){.tk-score{min-width:48px}}`;

function tkRow(s, withText) {
  const href = s.url || teknologi.hnLink(s);
  const ext = s.url ? ' rel="noopener nofollow" target="_blank"' : ' rel="noopener"';
  const preview = withText && s.text ? `<p class="tk-text">${escapeHtml(s.text.slice(0, 240))}${s.text.length > 240 ? '…' : ''}</p>` : '';
  return `<div class="tk-item"><div class="tk-score"><b>${s.points}</b><span>points</span></div><div class="tk-main">`
    + `<h3><a href="${escapeHtml(href)}"${ext}>${escapeHtml(s.title)}</a></h3>`
    + `<p class="tk-meta">${escapeHtml(teknologi.domainOf(s))} · ${teknologi.agoLabel(s.createdAt)} · by ${escapeHtml(s.author || 'anonymous')} · <a href="${escapeHtml(teknologi.hnLink(s))}" rel="noopener nofollow" target="_blank">${s.comments} comments</a></p>${preview}</div></div>`;
}

function teknologiNav() {
  return worldNav('Technology — tukuk.org/teknologi', [
    { href: '/teknologi', icon: '📰', name: 'Front page right now', blurb: 'The stories the world’s developers, founders and engineers are reading and arguing over at this very moment, ranked by community votes.' },
    { href: '/teknologi/new', icon: '🆕', name: 'Latest submissions', blurb: 'Everything just submitted to the Hacker News community in the past 48 hours — software, AI, security, hardware and the open web.' },
    { href: '/teknologi/show', icon: '🛠️', name: 'Show HN — things people built', blurb: 'New tools, libraries and products their makers just shipped and are demonstrating to the community for feedback.' },
    { href: '/teknologi/ask', icon: '💬', name: 'Ask HN — tech questions', blurb: 'Questions technologists ask each other: career advice, debugging war stories, “what should I read”, and hard engineering choices.' },
  ]);
}

function tkItemListLd(name, selfUrl, desc, stories) {
  return JSON.stringify({
    '@context': 'https://schema.org', '@type': 'ItemList', name,
    description: desc, url: selfUrl,
    numberOfItems: stories.length,
    itemListElement: stories.slice(0, 15).map((s, i) => ({
      '@type': 'ListItem', position: i + 1, name: s.title.slice(0, 160),
      url: s.url || teknologi.hnLink(s),
    })),
    publisher: { '@type': 'Organization', name: 'Tukuk-OS', url: 'https://tukuk.org' },
  }).replace(/</g, '\u003c');
}

function teknologiHubPage(stories) {
  const rows = stories.slice(0, 20).map((s) => tkRow(s, false)).join('');
  const body = `<p>This is the <b>live technology pulse</b> of tukuk.org: the stories the world’s developers, founders and engineers are reading and arguing over right now. The list is the front page of <b>Hacker News</b> — the oldest community-run tech newswire, where every story and every rank comes from readers’ votes, not an editorial desk. We mirror it through the public Algolia API and re-cache it on our server every ten minutes, so this page loads instantly and never overloads the source.</p>
  <div class="tk-topline"><span><b>${rows ? stories.length : 0}</b> stories ranked by the community</span><span class="meta">cached 10 min · auto-revalidated on our server</span></div>
  ${rows || '<p class="meta">The feed is briefly empty — reload in a minute.</p>'}
  <h2 class="section-title">How to read this page</h2>
  <p>Each row shows the story’s <b>point score</b> (up-votes minus down-votes), where it links, how long ago it was posted, who submitted it, and how many comments the discussion has drawn. Clicking the title opens the article itself; clicking the comment count opens the thread on Hacker News, where the argument usually happens. Because ranking is democratic, the front page mixes hard engineering news, security incidents, startup funding, scientific papers and the occasional keyboard review — that mix is exactly what makes it interesting.</p>
  <h2 class="section-title">Explore the other feeds</h2>
  <p>The <a href="/teknologi/new">latest submissions</a> show everything fresh off the wire before the vote has decided its fate. <a href="/teknologi/show">Show HN</a> is where people demonstrate things they just built — a good place to find a tool nobody has heard of yet. <a href="/teknologi/ask">Ask HN</a> is the community asking itself: career advice, debugging war stories and “what should I read next”.</p>
  <p class="meta">Stories and comments belong to their authors; the list comes from <a href="https://news.ycombinator.com" rel="noopener nofollow">Hacker News</a> via its public API and we do not alter the ranking. Outbound links are community-submitted and carry no endorsement. For our own long-form writing see the <a href="/blog">Blog</a>, <a href="/learn">Learn</a> and <a href="/wiki">Wiki</a>.</p>`;
  return worldDoc({
    title: 'Technology — Live Top Tech Stories & News Pulse | Tukuk-OS',
    desc: 'The live front page of the tech world: today’s top-ranked technology stories on software, AI, security, hardware and the open web, voted by the Hacker News community and mirrored free on tukuk.org.',
    selfUrl: 'https://tukuk.org/teknologi',
    heroTitle: '💻 Technology — Live Pulse', heroSub: 'Top tech stories right now · community-ranked · refreshed every 10 minutes',
    css: TK_CSS, body,
    ld: tkItemListLd('Top Technology Stories Right Now', 'https://tukuk.org/teknologi', 'The current community-ranked front page of technology stories.', stories),
  }, teknologiNav());
}

const TK_FEEDS = {
  new: {
    fn: teknologi.latest,
    title: 'Latest Technology Stories — New Submissions, Last 48 Hours | Tukuk-OS',
    desc: 'Every new technology story submitted to the Hacker News community in the last 48 hours — software, AI, security, hardware and the web — before the vote has ranked it.',
    heroTitle: '🆕 Latest Tech Stories', heroSub: 'Fresh submissions from the community · last 48 hours',
    intro: `<p>This is the wire <b>before the ranking</b>: every technology story the community submitted in the past 48 hours, newest first. It is the best place to spot a topic that is about to blow up — while it still has four votes and thirty comments instead of four hundred.</p>`,
  },
  show: {
    fn: teknologi.showHn,
    title: 'Show HN — New Tools, Apps and Projects People Just Built | Tukuk-OS',
    desc: 'Fresh “Show HN” posts from the Hacker News community: tools, libraries, apps and hardware their makers just built and are demonstrating for feedback, filtered to the ones with real traction.',
    heroTitle: '🛠️ Show HN', heroSub: 'Things builders just shipped · last 14 days · 20+ points',
    intro: `<p><b>Show HN</b> is where makers demonstrate something they built — a language, a game engine, a privacy tool, a kitchen gadget with firmware — and hand it to the community for feedback. We show the ones that drew real traction (twenty or more points) over the past two weeks; the comments often contain the author answering technical questions line by line.</p>`,
  },
  ask: {
    fn: teknologi.askHn,
    title: 'Ask HN — Questions the Tech Community Is Answering | Tukuk-OS',
    desc: 'The latest “Ask HN” questions with real answers: career advice, debugging war stories, learning paths and hard engineering choices, asked to the Hacker News community.',
    heroTitle: '💬 Ask HN', heroSub: 'Questions technologists ask each other · last 14 days',
    intro: `<p><b>Ask HN</b> turns the community into a help desk: “how did you get your first sysadmin job?”, “what are you reading this month?”, “has anyone actually run this at scale?”. The answers below come from practitioners, and the good questions rise by vote — we list the ones with traction from the past two weeks.</p>`,
  },
};

function teknologiFeedPage(f, stories) {
  const slug = f === TK_FEEDS.new ? 'new' : f === TK_FEEDS.show ? 'show' : 'ask';
  const withText = slug === 'ask';
  const rows = stories.map((s) => tkRow(s, withText)).join('');
  const selfUrl = `https://tukuk.org/teknologi/${slug}`;
  const body = `${f.intro}
  <div class="tk-topline"><span><b>${stories.length}</b> stories</span><span class="meta">cached 10 min · source: Hacker News community</span></div>
  ${rows || '<p class="meta">Nothing in the window right now — reload in a minute.</p>'}
  <h2 class="section-title">Other tech feeds</h2>
  <p>Back to the ranked <a href="/teknologi">front page</a>, or browse the other feeds above. Our own technology writing lives on the <a href="/blog">Blog</a> and in the <a href="/learn">Learn</a> library.</p>
  <p class="meta">Stories and comments belong to their authors, via <a href="https://news.ycombinator.com" rel="noopener nofollow">Hacker News</a>’ public API. Ranking shown as received; we do not edit the list.</p>`;
  return worldDoc({
    title: f.title, desc: f.desc, selfUrl,
    heroTitle: f.heroTitle, heroSub: f.heroSub,
    css: TK_CSS, body,
    ld: tkItemListLd(f.heroTitle, selfUrl, f.desc, stories),
  }, teknologiNav());
}

function teknologiBusy() {
  return `<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,follow"><title>Technology feed briefly unavailable | Tukuk-OS</title><body style="font-family:system-ui,Arial,sans-serif;max-width:640px;margin:64px auto;padding:20px;line-height:1.6"><h1>💻 Technology</h1><p>The tech feed is briefly unavailable while the source is re-checked. Cached copies usually return within a minute.</p><p><a href="/teknologi">Back to Technology</a> · <a href="/">Tukuk-OS</a></p></body></html>`;
}

function teknologiNotFound(q) {
  return worldDoc({
    title: 'Tech feed not found | Tukuk-OS',
    desc: 'That technology feed does not exist — browse the live front page, latest, Show HN and Ask HN feeds instead.',
    selfUrl: 'https://tukuk.org/teknologi', robots: 'noindex,follow',
    heroTitle: 'Feed not found', heroSub: `“${escapeHtml(String(q || ''))}” is not a tech feed`,
    css: TK_CSS,
    body: `<p>Try one of the live feeds: <a href="/teknologi">front page</a>, <a href="/teknologi/new">latest</a>, <a href="/teknologi/show">Show HN</a> or <a href="/teknologi/ask">Ask HN</a>.</p>`,
  }, teknologiNav());
}

// ── /peta — Maps & Navigation (OSRM routing + Nominatim geocoding, keyless) ────
const PETA_CSS = `.peta-form{display:flex;gap:10px;flex-wrap:wrap;align-items:flex-end;margin:16px 0}
.peta-form label{display:flex;flex-direction:column;gap:4px;font-size:.85rem;color:var(--muted,#9aa3b2)}
.peta-form input,.peta-form select{padding:8px 10px;border:1px solid var(--line);border-radius:8px;background:var(--bg,#0f1115);color:var(--text,#e6e9ef);font:inherit;min-width:170px}
.peta-btn{border:1px solid var(--line);border-radius:8px;background:var(--panel,#171a21);color:var(--text,#e6e9ef);padding:8px 14px;font:inherit;cursor:pointer}
.peta-btn:hover{border-color:var(--accent,#4c8dff)}
.peta-btn.primary{background:var(--accent,#4c8dff);border-color:transparent;color:#fff;font-weight:700}
#peta-status{font-size:.88rem;color:var(--muted,#9aa3b2);align-self:center;min-height:1.2em}
.peta-grid{display:grid;grid-template-columns:2fr 1fr;gap:14px;margin:14px 0}
#peta-map{height:480px;border:1px solid var(--line);border-radius:12px;z-index:1}
#peta-side{border:1px solid var(--line);border-radius:12px;background:var(--panel,#171a21);padding:12px 14px;max-height:480px;overflow:auto}
.peta-sum{font-weight:800;margin:0 0 10px}
.peta-step{display:flex;justify-content:space-between;gap:10px;padding:7px 0;border-bottom:1px solid var(--line);font-size:.9rem;line-height:1.4}
.peta-step .d{color:var(--muted,#9aa3b2);white-space:nowrap}
@media(max-width:820px){.peta-grid{grid-template-columns:1fr}#peta-map{height:360px}}`;

function petaNav() {
  return worldNav('Maps & places — tukuk.org', [
    { href: '/peta', icon: '🗺️', name: 'Maps & Navigation', blurb: 'Route between any two places on Earth — driving, cycling or walking — with a full turn-by-turn list, free and without an account.' },
    { href: '/peta/jarak', icon: '📏', name: 'Distance Calculator', blurb: 'How far, really? Straight through the globe versus the honest road distance between any two places, with the detour factor.' },
    { href: '/peta/matahari', icon: '🌅', name: 'Sunrise & Sunset', blurb: 'Sunrise, sunset, solar noon, day length and twilight for any place on Earth and any date — computed from arithmetic, not an API.' },
    { href: '/peta/jam', icon: '🕰️', name: 'World Clock', blurb: 'What time is it in Tokyo right now? Live clocks for the world’s major cities plus any city you search — exact offsets and DST, from the IANA time zone database.' },
    { href: '/peta/langit', icon: '🛰️', name: 'Live Earth — Satellite', blurb: 'A full-window satellite view of the planet: today’s true-color pass, night city lights, Blue Marble and street-level zoom — fly to any place.' },
    { href: '/traffic', icon: '🚦', name: 'Tukuk Traffic', blurb: 'The community road board: live jams, accidents, police checks, hazards and closures, fading away automatically as they age.' },
    { href: '/cuaca/peta', icon: '🌦️', name: 'World weather map', blurb: 'A live Leaflet map of weather across the planet — rain, heat and storms at a glance.' },
    { href: '/kota', icon: '🏙️', name: 'World cities', blurb: 'Profiles of the world’s major cities — where they are, how big, and what they are known for.' },
  ]);
}

function petaPage() {
  const modeMeta = JSON.stringify(peta.MODE_LABEL).replace(/</g, '\\u003c');
  const body = `<p><b>Maps &amp; Navigation</b> plots a real route between any two places on Earth and walks you through it turn by turn. Type two place names — a city, an address, a landmark — or click the map, pick driving, cycling or walking, and press Go. One click in the view panel flips the whole map between the open street map, high-resolution <b>satellite imagery</b>, NASA's <b>daily true-color satellite pass</b> — imagery composited from satellites that flew over today — and the <b>night-lights</b> band that shows where people actually live after dark. The route is computed by <b>OSRM</b> on <b>OpenStreetMap</b> data, the same open engines that power community maps worldwide, proxied through our own server and cached — so nothing is sent about you, and the page stays fast even when the public routers are busy.</p>
  <div class="peta-form">
    <label>From <input id="peta-from" type="text" placeholder="e.g. Kuala Lumpur" autocomplete="off"></label>
    <label>To <input id="peta-to" type="text" placeholder="e.g. Penang" autocomplete="off"></label>
    <label>Mode <select id="peta-mode"><option value="car">🚗 Driving</option><option value="bike">🚲 Cycling</option><option value="foot">🚶 Walking</option></select></label>
    <button class="peta-btn primary" id="peta-go" type="button">Go</button>
    <button class="peta-btn" id="peta-me" type="button">📍 Start at my location</button>
    <button class="peta-btn" id="peta-clear" type="button">Clear</button>
    <span id="peta-status"></span>
  </div>
  <p class="meta">Tip: <b>left-click</b> the map to set the destination, <b>right-click (or long-press)</b> to set the start — then drag the pins to fine-tune. Place names beat raw coordinates; blank a box to use its pin instead.</p>
  <div class="peta-grid">
    <div id="peta-map" role="application" aria-label="Route map"></div>
    <aside id="peta-side"><h3 style="margin:0 0 8px">Directions</h3><p class="meta">Your turn-by-turn list will appear here.</p></aside>
  </div>
  <noscript><p>JavaScript is required for the interactive map and routing. Everything else on tukuk.org works without it — try the <a href="/cuaca">world weather</a>.</p></noscript>
  <h2 class="section-title">How the route is built</h2>
  <p>Your place names are resolved by <b>Nominatim</b> (OpenStreetMap’s own search) and the road path by <b>OSRM</b>, one of the fastest open-source routing engines in existence — it answers in milliseconds across entire countries. Both run against the worldwide OpenStreetMap map, drawn and maintained by millions of volunteers, which is why remote villages and footpaths appear just like motorways. Our server caches every answer briefly, so repeated lookups never touch the public services.</p>
  <h2 class="section-title">What it is not</h2>
  <p>This is a route <b>planner</b>, not a live navigation co-pilot: there are no voice prompts, no speed cameras on the route and no traffic-aware rerouting — for the community’s eyes on the road itself see <a href="/traffic">Tukuk Traffic</a>. Distances and times assume free-flowing conditions; road works, closures and local rules always win. Some pairs genuinely have no road between them (islands, or Borneo and the Peninsula without a ferry) — the router will say so honestly rather than invent a path.</p>
  <p class="meta">Map data &amp; © <a href="https://www.openstreetmap.org/copyright" rel="noopener nofollow">OpenStreetMap</a> contributors; routing by <a href="http://project-osrm.org/" rel="noopener nofollow">OSRM</a>; search by <a href="https://nominatim.org/" rel="noopener nofollow">Nominatim</a>. Tiles rendered with Leaflet; satellite imagery © <a href="https://www.esri.com/content/dam/esrisites/en-us/media/legal/feature-article-licensing.pdf" rel="noopener nofollow">Esri</a>, Maxar &amp; Earthstar Geographics; daily true-color by <a href="https://worldview.earthdata.nasa.gov" rel="noopener nofollow">NASA GIBS</a> (VIIRS/Suomi-NPP, renewed every day). No coordinates leave your browser except the two endpoints you search.</p>`;
  const script = `<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css">`
    + `<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js" defer></script>`
    + `<script>(function(){var MODE=${modeMeta};var map=null,start=null,dest=null,mkS=null,mkD=null,line=null;
function esc(x){return String(x).replace(/[&<>]/g,function(c){return({'&':'&amp;','<':'&lt;','>':'&gt;'})[c];});}
function status(t){document.getElementById('peta-status').textContent=t||'';}
function fmtD(m){return m>=1000?(m/1000).toFixed(1)+' km':Math.round(m)+' m';}
function fmtT(s){var min=Math.round(s/60);if(min<60)return min+' min';var h=Math.floor(min/60);return h+' h '+(min%60)+' min';}
function pin(which,lat,lon){var mk=which==='s'?mkS:mkD;var ll=[lat,lon];
  if(!mk){mk=L.marker(ll,{draggable:true,title:which==='s'?'Start':'Destination'}).addTo(map);mk.on('dragend',function(){var p=mk.getLatLng();var c={lat:p.lat,lon:p.lng};if(which==='s')start=c;else dest=c;});}
  else mk.setLatLng(ll);
  if(which==='s'){mkS=mk;start={lat:lat,lon:lon};}else{mkD=mk;dest={lat:lat,lon:lon};}}
function resolveBox(id,pinPt){var v=document.getElementById(id).value.trim();
  if(!v){if(pinPt)return Promise.resolve(pinPt);return Promise.reject(new Error('fill both boxes or click the map'));}
  var m=v.split(',');if(m.length===2){var a=parseFloat(m[0]),b=parseFloat(m[1]);if(isFinite(a)&&isFinite(b)&&Math.abs(a)<=90&&Math.abs(b)<=180)return Promise.resolve({lat:a,lon:b});}
  return fetch('/api/peta/geocode?q='+encodeURIComponent(v)).then(function(x){return x.json();}).then(function(j){if(!j.ok||!j.results||!j.results.length)throw new Error(j.error||'place not found');return {lat:j.results[0].lat,lon:j.results[0].lon};});}
function go(){status('finding places…');var mode=document.getElementById('peta-mode').value;
  Promise.all([resolveBox('peta-from',start),resolveBox('peta-to',dest)]).then(function(ps){
    pin('s',ps[0].lat,ps[0].lon);pin('d',ps[1].lat,ps[1].lon);
    status('routing…');
    return fetch('/api/peta/route?from='+ps[0].lat+','+ps[0].lon+'&to='+ps[1].lat+','+ps[1].lon+'&mode='+mode).then(function(x){return x.json();});
  }).then(function(j){
    if(!j.ok)throw new Error(j.error||'routing failed');
    draw(j);status('');
  }).catch(function(e){status('⚠ '+(e.message||e));});}
function draw(j){if(line){map.removeLayer(line);line=null;}
  if(!j.coords||!j.coords.length){status('⚠ empty route');return;}
  line=L.polyline(j.coords,{color:'#4c8dff',weight:5,opacity:.85}).addTo(map);
  map.fitBounds(line.getBounds().pad(0.12));
  var side=document.getElementById('peta-side');
  var html='<p class="peta-sum">'+(MODE[j.mode]||j.mode)+' · '+fmtD(j.distance)+' · about '+fmtT(j.duration)+'</p>';
  html+=j.steps.map(function(s,i){return '<div class="peta-step"><span>'+(i+1)+'. '+esc(s.text)+'</span><span class="d">'+fmtD(s.distance)+'</span></div>';}).join('');
  side.innerHTML=html;}
function boot(){if(!window.L){setTimeout(boot,300);return;}
  map=L.map('peta-map',{zoomControl:true}).setView([20,100],3);
  var osm=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'\\u00a9 OpenStreetMap'});
  var sat=L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{maxZoom:19,attribution:'Imagery \\u00a9 Esri, Maxar, Earthstar Geographics'});
  var ref=L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/Reference/World_Boundaries_and_Places/MapServer/tile/{z}/{y}/{x}',{maxZoom:19});
  var hybrid=L.layerGroup([sat,ref]);
  var d=new Date();var gd=d.getUTCFullYear()+'-'+('0'+(d.getUTCMonth()+1)).slice(-2)+'-'+('0'+d.getUTCDate()).slice(-2);
  var live=L.tileLayer('https://gibs.earthdata.nasa.gov/wmts/epsg3857/best/VIIRS_SNPP_CorrectedReflectance_TrueColor/default/'+gd+'/GoogleMapsCompatible_Level9/{z}/{y}/{x}.jpeg',{maxNativeZoom:9,maxZoom:12,attribution:'NASA GIBS — true-color satellite, renewed daily ('+gd+')'});
  var night=L.tileLayer('https://gibs.earthdata.nasa.gov/wmts/epsg3857/best/VIIRS_NOAA20_DayNightBand/default/'+gd+'/GoogleMapsCompatible_Level7/{z}/{y}/{x}.png',{maxNativeZoom:7,maxZoom:12,attribution:'NASA GIBS — NOAA-20 day/night lights, renewed daily ('+gd+')'});
  var pref='';try{pref=localStorage.getItem('peta-view')||'';}catch(e){}
  (pref==='sat'?hybrid:pref==='live'?live:pref==='night'?night:osm).addTo(map);
  L.control.layers({'🗺 Map':osm,'🛰 Satellite':hybrid,'☀ Live true-color (daily)':live,'🌙 Night lights (daily)':night},null,{collapsed:window.innerWidth<720}).addTo(map);
  map.on('baselayerchange',function(e){var k=e.layer===hybrid?'sat':(e.layer===live?'live':(e.layer===night?'night':'map'));try{localStorage.setItem('peta-view',k);}catch(x){}});
  map.on('click',function(e){pin('d',e.latlng.lat,e.latlng.lng);status('destination set — left-click again to move it, right-click for start');});
  map.on('contextmenu',function(e){e.originalEvent.preventDefault();pin('s',e.latlng.lat,e.latlng.lng);status('start set — press Go');});
  document.getElementById('peta-go').onclick=go;
  document.getElementById('peta-mode').onchange=function(){if(start&&dest)go();};
  document.getElementById('peta-clear').onclick=function(){document.getElementById('peta-from').value='';document.getElementById('peta-to').value='';if(mkS){map.removeLayer(mkS);mkS=null;}if(mkD){map.removeLayer(mkD);mkD=null;}if(line){map.removeLayer(line);line=null;}start=null;dest=null;document.getElementById('peta-side').innerHTML='<h3 style=\"margin:0 0 8px\">Directions<\\/h3><p class=\"meta\">Pick two places.</p>';status('');};
  document.getElementById('peta-me').onclick=function(){if(!navigator.geolocation){status('⚠ browser has no location');return;}status('locating…');navigator.geolocation.getCurrentPosition(function(p){pin('s',p.coords.latitude,p.coords.longitude);status('start pinned at your location — type a destination and Go');},function(e){status('⚠ location denied');});};
}
boot();})();</script>`;
  return worldDoc({
    title: 'Maps & Navigation — Free Turn-by-Turn Route Planner (Driving, Cycling, Walking) | Tukuk-OS',
    desc: 'Plan a route between any two places on Earth for free: driving, cycling or walking directions with distance, travel time and a full turn-by-turn list, powered by open OpenStreetMap engines. No account, no API key, no tracking.',
    selfUrl: 'https://tukuk.org/peta',
    heroTitle: '🗺️ Maps & Navigation', heroSub: 'Free routes worldwide · driving, cycling & walking · turn-by-turn',
    css: PETA_CSS, body: body + script,
    ld: JSON.stringify({
      '@context': 'https://schema.org', '@type': 'WebApplication', name: 'Tukuk Maps & Navigation',
      applicationCategory: 'NavigationApplication', operatingSystem: 'Web browser',
      description: 'Free turn-by-turn route planner for driving, cycling and walking anywhere in the world, built on OpenStreetMap data with OSRM routing.',
      url: 'https://tukuk.org/peta', offers: { '@type': 'Offer', price: '0', priceCurrency: 'USD' },
    }).replace(/</g, '\\u003c')
  }, petaNav());
}

function petaBusy() {
  return `<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,follow"><title>Maps briefly unavailable | Tukuk-OS</title><body style="font-family:system-ui,Arial,sans-serif;max-width:640px;margin:64px auto;padding:20px;line-height:1.6"><h1>🗺️ Maps &amp; Navigation</h1><p>The map page failed to render while the server reloaded. Please refresh in a moment.</p><p><a href="/">Back to Tukuk-OS</a></p></body></html>`;
}

// ── /peta/langit — Live Earth: a full-window satellite view of the planet ─────
// Day side = NASA GIBS VIIRS true-color (renewed daily); night side = VIIRS
// NOAA-20 day/night band (city lights, also current); Blue Marble is the crisp
// always-on reference; Esri World Imagery zooms to street level. Every layer is
// free & keyless and pulled straight by the visitor's browser — our server only
// renders the page and proxies place searches through the existing peta cache.
const LANGIT_CSS = PETA_CSS + `.langit-wrap{position:relative;margin:14px 0;border:1px solid var(--line);border-radius:12px;overflow:hidden}
#langit-map{height:min(78vh,820px);width:100%;z-index:1}
.langit-bar{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin:12px 0}
.langit-bar input{padding:8px 10px;border:1px solid var(--line);border-radius:8px;background:var(--bg,#0f1115);color:var(--text,#e6e9ef);font:inherit;min-width:200px}
.langit-day{font-size:.82rem;color:var(--muted,#9aa3b2)}
.langit-wrap:fullscreen{border-radius:0} .langit-wrap:fullscreen #langit-map{height:100vh}
.langit-hint{font-size:.9rem;color:var(--muted,#9aa3b2);margin:6px 0 0}`;

function langitPage() {
  const body = `<p><b>Live Earth</b> is the whole planet under your fingers, seen from space. Flip between <b>today's true-color satellite pass</b>, the <b>night side</b> where city lights trace where people actually live, a crisp <b>Blue Marble</b> reference, and a <b>high-resolution</b> street-level satellite — all keyless imagery served straight to your browser. Search any place to fly there, or use the layer box (top-right) to change what you are seeing.</p>
  <div class="langit-bar">
    <input id="langit-q" type="text" placeholder="Fly to a place… e.g. Cairo, the Alps, Tokyo" autocomplete="off" aria-label="Search a place to fly to">
    <button class="peta-btn primary" id="langit-go" type="button">🔎 Fly there</button>
    <button class="peta-btn" id="langit-full" type="button">⤢ Fullscreen</button>
    <span class="langit-day" id="langit-status"></span>
  </div>
  <div class="langit-wrap"><div id="langit-map" role="application" aria-label="Live satellite Earth"></div></div>
  <p class="langit-hint" id="langit-day"></p>
  <noscript><p>JavaScript is required for the live satellite globe. The rest of tukuk.org works without it — try the <a href="/nasa/earth">EPIC whole-Earth picture</a> or the <a href="/cuaca/peta">world weather map</a>.</p></noscript>
  <h2 class="section-title">What each view actually is</h2>
  <p><b>True-color (day)</b> is a mosaic the satellite stitches every single day from light reflected off clouds, ocean and land — so haze, smoke plumes and the swirl of a developing storm are all real and current. <b>Night lights</b> come from a day/night band sensor sensitive enough to pick up individual cities, gas flares and even moonlight glinting off clouds; the lights you see are genuinely where people are after dark. <b>Blue Marble</b> is NASA's cleaned composite reference — cloudless and sharp, ideal for reading coastlines and deserts. <b>High-resolution</b> switches to a commercial satellite basemap that lets you zoom into airports, districts and harbours.</p>
  <h2 class="section-title">Why it is free (and what it is not)</h2>
  <p>Every layer here is published by NASA's Global Imagery Browse Services or a national geographic archive for exactly this kind of use — no account, no API key, no usage limit on your side. The imagery is refreshed on the providers' schedule (typically about a day behind for the daily composites), so this is a living snapshot of the planet, not a real-time video feed, and clouds are sometimes in the way — that is the honest weather, not a bug. For routing between places use <a href="/peta">Maps &amp; Navigation</a>; for a single full-disk portrait of Earth use <a href="/nasa/earth">EPIC</a>; and for the fuller story behind these layers — why a daily composite beats a live feed — read <a href="/blog/see-earth-from-space-today-free-satellite-imagery">how free satellite imagery actually works</a> — then go deeper on <a href="/blog/reading-earth-at-night-what-city-lights-reveal">what city lights reveal about us</a> and <a href="/blog/weather-satellites-vs-map-satellites">weather vs map satellites</a>.</p>
  <p class="meta">Imagery: <a href="https://www.earthdata.nasa.gov/centers/goddard-earths-gibs-science-team/gibs" rel="noopener nofollow">NASA GIBS</a> (VIIRS true-color &amp; NOAA-20 day/night band), <a href="https://visibleearth.nasa.gov/collection/1484/blue-marble" rel="noopener nofollow">NASA Blue Marble</a>, <a href="https://www.esri.com/en-us/arcgis/products/arcgis-world-imagery/overview" rel="noopener nofollow">Esri World Imagery</a>. Rendered with Leaflet. Your view stays in your browser — no coordinates are stored.</p>`;
  const script = `<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css">`
    + `<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js" defer></script>`
    + `<script>(function(){var map=null,mark=null;
function st(t){document.getElementById('langit-status').textContent=t||'';}
function gibs(layer,lvl,ext,date,nz,mz,attr){return L.tileLayer('https://gibs.earthdata.nasa.gov/wmts/epsg3857/best/'+layer+'/default/'+date+'/GoogleMapsCompatible_Level'+lvl+'/{z}/{y}/{x}.'+ext,{maxNativeZoom:nz,maxZoom:mz,attribution:attr});}
function boot(){if(!window.L){setTimeout(boot,300);return;}
  map=L.map('langit-map',{zoomControl:true,minZoom:1,maxZoom:18,worldCopyJump:true}).setView([22,12],2);
  var d=new Date();var gd=d.getUTCFullYear()+'-'+('0'+(d.getUTCMonth()+1)).slice(-2)+'-'+('0'+d.getUTCDate()).slice(-2);
  document.getElementById('langit-day').textContent='☉ True-color & night lights are dated '+gd+' (UTC) — NASA renews these composites about every 24 hours.';
  var day=gibs('VIIRS_SNPP_CorrectedReflectance_TrueColor',9,'jpeg',gd,9,12,'© NASA GIBS — VIIRS true-color (daily)');
  var night=gibs('VIIRS_NOAA20_DayNightBand',7,'png',gd,7,12,'© NASA GIBS — VIIRS NOAA-20 day/night band');
  var marble=L.tileLayer('https://gibs.earthdata.nasa.gov/wmts/epsg3857/best/BlueMarble_NextGeneration/default/2015-07-08/GoogleMapsCompatible_Level8/{z}/{y}/{x}.jpeg',{maxNativeZoom:8,maxZoom:12,attribution:'© NASA Blue Marble'});
  var hi=L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{maxZoom:18,attribution:'© Esri, Maxar, Earthstar Geographics'});
  var labels=L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/Reference/World_Boundaries_and_Places/MapServer/tile/{z}/{y}/{x}',{maxZoom:18});
  day.addTo(map);
  L.control.layers({'🌞 True-color (today)':day,'🌙 Night lights':night,'🗲 Blue Marble':marble,'🛰️ High-res satellite':hi},{'🏷️ Place labels':labels},{collapsed:window.innerWidth<720}).addTo(map);
  document.getElementById('langit-go').onclick=fly;document.getElementById('langit-q').addEventListener('keydown',function(e){if(e.key==='Enter')fly();});
  document.getElementById('langit-full').onclick=function(){var w=document.querySelector('.langit-wrap');if(document.fullscreenElement){document.exitFullscreen&&document.exitFullscreen();}else{w.requestFullscreen&&w.requestFullscreen();}};
  document.addEventListener('fullscreenchange',function(){setTimeout(function(){map.invalidateSize();},200);});
  if('serviceWorker' in navigator)addEventListener('load',function(){navigator.serviceWorker.register('/sw.js').catch(function(){});});
}
function fly(){var v=document.getElementById('langit-q').value.trim();if(!v){st('type a place first');return;}
  var m=v.split(',');if(m.length===2){var a=parseFloat(m[0]),b=parseFloat(m[1]);if(isFinite(a)&&isFinite(b)&&Math.abs(a)<=90&&Math.abs(b)<=180){go(a,b,v);return;}}
  st('finding '+v+'…');
  fetch('/api/peta/geocode?q='+encodeURIComponent(v)).then(function(x){return x.json();}).then(function(j){
    if(!j.ok||!j.results||!j.results.length){st('⚠ place not found');return;}var p=j.results[0];go(p.lat,p.lon,p.label);
  }).catch(function(){st('⚠ search unavailable');});}
function go(lat,lon,label){if(mark)map.removeLayer(mark);mark=L.circleMarker([lat,lon],{radius:7,color:'#fff',weight:2,fillColor:'#4c8dff',fillOpacity:.9}).addTo(map);map.flyTo([lat,lon],6,{duration:2});st(label?String(label).slice(0,60):'');}
boot();})();</script>`;
  return worldDoc({
    title: 'Live Earth — Real Satellite View of the Planet (Day, Night Lights, Blue Marble) | Tukuk-OS',
    desc: 'A full-screen live satellite view of Earth: the latest NASA true-color pass, night lights from the day/night band, the cloudless Blue Marble and a high-res street-level satellite. Fly to any place. Free, no account, no API key.',
    selfUrl: 'https://tukuk.org/peta/langit',
    heroTitle: '🛰️ Live Earth', heroSub: "Today's satellite view of the whole planet · day, night lights & high-res · fly anywhere",
    css: LANGIT_CSS, body: body + script,
    head: '\n<link rel="manifest" href="/manifest-langit.json">',
    ld: JSON.stringify({
      '@context': 'https://schema.org', '@type': 'WebApplication', name: 'Tukuk Live Earth',
      applicationCategory: 'ReferenceApplication', operatingSystem: 'Web browser',
      description: 'Full-screen live satellite view of Earth using NASA GIBS true-color and day/night imagery, NASA Blue Marble and Esri high-res imagery, with place search.',
      url: 'https://tukuk.org/peta/langit', offers: { '@type': 'Offer', price: '0', priceCurrency: 'USD' },
    }).replace(/</g, '\\u003c'),
  }, petaNav());
}

// ── /peta/jarak + /peta/matahari — the two map companion tools ────────────────
// Distance = great-circle arithmetic plus the existing road router; sun times
// = textbook solar position computed on our own server. Neither invents data:
// missing roads and polar days/nights are reported exactly as found.
const PJ_CSS = PETA_CSS + `.pj-out{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:14px 0}
.pj-card{border:1px solid var(--line);border-radius:12px;padding:14px 10px;text-align:center;background:var(--panel,#171a21)}
.pj-card b{display:block;font-size:1.3rem;color:var(--accent,#4c8dff)}
.pj-card i{display:block;font-style:normal;font-size:.85rem;color:var(--muted,#9aa3b2);margin-top:2px}
.pj-card span{font-size:.78rem;color:var(--muted,#9aa3b2)}
@media(max-width:720px){.pj-out{grid-template-columns:repeat(2,1fr)}}`;

function jarakPage() {
  const body = `<p><b>How far is it, really?</b> Ask two questions and get both numbers: the straight line <i>through the globe</i> — the shortest path a bird, a radio wave or an antipode map would take — and the honest <b>road distance</b> a vehicle must actually cover. Type two place names and press Measure.</p>
  <div class="peta-form">
    <label>From <input id="pj-from" type="text" placeholder="e.g. Kuala Lumpur" autocomplete="off"></label>
    <label>To <input id="pj-to" type="text" placeholder="e.g. Singapore" autocomplete="off"></label>
    <label>Road <select id="pj-mode"><option value="car">🚗 Driving</option><option value="bike">🚲 Cycling</option><option value="foot">🚶 Walking</option></select></label>
    <button class="peta-btn primary" id="pj-go" type="button">Measure</button>
    <span id="pj-status"></span>
  </div>
  <div id="pj-out" class="pj-out"><div class="pj-card"><b>—</b><span>straight line</span></div><div class="pj-card"><b>—</b><span>by road</span></div><div class="pj-card"><b>—</b><span>road time</span></div><div class="pj-card"><b>—</b><span>detour factor</span></div></div>
  <noscript><p>JavaScript is required for the calculator. The <a href="/peta">route planner</a> needs it too — everything else on tukuk.org works without it.</p></noscript>
  <h2 class="section-title">Why the straight line is a curve</h2>
  <p>The Earth is a ball, so the shortest path between two places is not a ruler line but a <b>great circle</b> — an arc hugging the largest circle you can draw around the globe. Long-haul flights bow toward the poles for exactly this reason, and the number here uses the <b>haversine formula</b> from spherical trigonometry with the Earth’s mean radius of 6,371 km (one full turn around the planet ≈ 40,075 km). A handy scale: 1° of latitude ≈ 111 km, and 1 minute of latitude ≈ 1.85 km — the <b>nautical mile</b>, born from the globe itself.</p>
  <h2 class="section-title">Reading the detour factor</h2>
  <p>Roads bend around mountains, coastlines and borders, so the driving number is always at least the straight one. The <b>ratio</b> is the interesting part: ~1.0–1.2 means an easy land corridor, 1.5+ means the terrain is arguing with the ruler, and “no route” is honest geography — islands have ferries, and you cannot drive from Malaysian Borneo to the Peninsula without one. Free-flow times ignore traffic; for today’s road reality see <a href="/traffic">Tukuk Traffic</a>. Related reading: <a href="/blog/latitude-longitude-explained">latitude &amp; longitude explained</a> and <a href="/blog/places-you-cannot-drive-to">places you cannot drive to</a> — and for the road itself, <a href="/peta">Maps &amp; Navigation</a>.</p>
  <p class="meta">Places resolved by Nominatim (cached on our server); roads by OSRM on OpenStreetMap data; the straight line is pure arithmetic and never touches a third party.</p>`;
  const script = `<script>(function(){
function esc(x){return String(x).replace(/[&<>]/g,function(c){return({'&':'&amp;','<':'&lt;','>':'&gt;'})[c];});}
function status(t){document.getElementById('pj-status').textContent=t||'';}
function fmtKm(k){return k>=100?Math.round(k).toLocaleString('en-US')+' km':k>=10?k.toFixed(1)+' km':k.toFixed(2)+' km';}
function fmtMin(m){return m<90?m+' min':Math.floor(m/60)+' h '+(m%60)+' min';}
function resolveBox(id){var v=document.getElementById(id).value.trim();
  if(!v)throw new Error('fill in both places');
  var m=v.split(',');if(m.length===2){var a=parseFloat(m[0]),b=parseFloat(m[1]);if(isFinite(a)&&isFinite(b)&&Math.abs(a)<=90&&Math.abs(b)<=180)return Promise.resolve({lat:a,lon:b});}
  return fetch('/api/peta/geocode?q='+encodeURIComponent(v)).then(function(x){return x.json();}).then(function(j){if(!j.ok||!j.results||!j.results.length)throw new Error(j.error||'place not found');return {lat:j.results[0].lat,lon:j.results[0].lon};});}
function render(j){var o=document.getElementById('pj-out');
  var cards='<div class="pj-card"><b>'+fmtKm(j.straightKm)+'</b><span>'+Math.round(j.straightKm*0.621371).toLocaleString('en-US')+' miles</span><span>straight through the globe</span></div>';
  if(j.road){var det=j.straightKm>1?(j.road.km/j.straightKm):null;
    cards+='<div class="pj-card"><b>'+fmtKm(j.road.km)+'</b><span>by '+esc(j.mode)+'</span><span>real road distance</span></div>'
      +'<div class="pj-card"><b>'+fmtMin(j.road.min)+'</b><span>free-flow</span><span>time on the road</span></div>'
      +'<div class="pj-card"><b>'+(det?det.toFixed(2)+'×':'—')+'</b><span>road ÷ straight</span><span>detour factor</span></div>';
  }else cards+='<div class="pj-card"><b>no route</b><span>'+esc(j.mode)+'</span><span>'+esc(j.roadError||'not connected')+'</span></div><div class="pj-card"><b>—</b><span>detour</span><span>needs a road</span></div>';
  o.innerHTML=cards;}
function go(){status('measuring…');var mode=document.getElementById('pj-mode').value;
  Promise.all([resolveBox('pj-from'),resolveBox('pj-to')]).then(function(ps){
    return fetch('/api/peta/distance?from='+ps[0].lat+','+ps[0].lon+'&to='+ps[1].lat+','+ps[1].lon+'&mode='+mode).then(function(x){return x.json();});
  }).then(function(j){if(!j.ok)throw new Error(j.error||'failed');render(j);status('');
  }).catch(function(e){status('⚠ '+(e.message||e));});}
document.getElementById('pj-go').onclick=go;
['pj-from','pj-to'].forEach(function(id){document.getElementById(id).addEventListener('keydown',function(e){if(e.key==='Enter')go();});});
document.getElementById('pj-mode').onchange=function(){go();};
})();</script>`;
  return worldDoc({
    title: 'Distance Calculator — Straight Line vs Road Distance Between Any Two Places | Tukuk-OS',
    desc: 'Measure the true distance between any two places on Earth: great-circle (as the crow flies) in km and miles, the real road distance and time, and the detour factor between them. Free, no account, open data.',
    selfUrl: 'https://tukuk.org/peta/jarak',
    heroTitle: '📏 Distance Calculator', heroSub: 'Straight through the globe vs the honest road · any two places on Earth',
    css: PJ_CSS, body: body + script,
    ld: JSON.stringify({
      '@context': 'https://schema.org', '@type': 'WebApplication', name: 'Tukuk Distance Calculator',
      applicationCategory: 'UtilityApplication', operatingSystem: 'Web browser',
      description: 'Great-circle and road distance calculator for any two places on Earth, with travel time and detour factor.',
      url: 'https://tukuk.org/peta/jarak', offers: { '@type': 'Offer', price: '0', priceCurrency: 'USD' },
    }).replace(/</g, '\\u003c'),
  }, petaNav());
}

function matahariPage() {
  const body = `<p><b>Sunrise &amp; Sunset</b> for any place on Earth and any date: when the sun actually crosses the horizon, when solar noon falls, how long the day lasts, and when civil twilight begins and ends. The arithmetic runs on our own server from the textbook solar-position algorithm — no API can be down, rate-limited or sold — and it matches printed almanacs to within a minute or two.</p>
  <div class="peta-form">
    <label>Place <input id="pj-place" type="text" placeholder="e.g. Reykjavík" autocomplete="off"></label>
    <label>Date <input id="pj-date" type="date"></label>
    <button class="peta-btn primary" id="pj-go" type="button">Compute</button>
    <span id="pj-status"></span>
  </div>
  <div id="pj-out" class="pj-out"><div class="pj-card"><b>—</b><span>sunrise</span></div><div class="pj-card"><b>—</b><span>solar noon</span></div><div class="pj-card"><b>—</b><span>sunset</span></div><div class="pj-card"><b>—</b><span>day length</span></div></div>
  <p class="meta" id="pj-extra"></p>
  <noscript><p>JavaScript is required for the calculator — everything else on tukuk.org works without it.</p></noscript>
  <h2 class="section-title">Why solar noon is not 12:00</h2>
  <p>Every clock rounds the Sun’s behaviour to a tidy time zone, but the Sun does not negotiate. True <b>solar noon</b> — when the sun due south (or north) climbs highest — drifts up to about 15 minutes back and forth all year from the <b>equation of time</b> (Earth’s tilted, slightly squashed orbit), and then by up to a full hour or more from your time zone’s political width. That is why the noon row here rarely reads 12:00, and why the <a href="/blog/time-zones-explained">time zone guide</a> is worth your five minutes.</p>
  <h2 class="section-title">What the numbers include</h2>
  <p>Sunrise and sunset are the moment’s <b>upper edge</b> of the sun touching the horizon, with air <b>refraction</b> built in (the atmosphere bends light about half a degree, lengthening every day on Earth by a handful of minutes). Civil twilight marks the sun 6° below the horizon — the usual line between “daylight enough to read outside” and not. Inside the Arctic and Antarctic circles the sun may never rise or never set, and the page says exactly that instead of inventing a time. On reading the clock rows: the big figure is UTC — universal, unambiguous — and the small one is the <b>nearest standard meridian</b> estimate, which can differ from the political clock by an hour or two. Related: <a href="/blog/latitude-longitude-explained">latitude &amp; longitude</a>, <a href="/peta/jarak">distance calculator</a>, <a href="/peta">maps &amp; navigation</a>.</p>
  <p class="meta">Algorithm: mean anomaly → ecliptic longitude → declination + equation of time → hour angle at zenith 90.833° (and 96° for civil twilight). Place names resolved by Nominatim, cached on our server.</p>`;
  const script = `<script>(function(){
function esc(x){return String(x).replace(/[&<>]/g,function(c){return({'&':'&amp;','<':'&lt;','>':'&gt;'})[c];});}
function pad(n){return (n<10?'0':'')+n;}
function hhmm(m){var t=Math.round(m);return pad(Math.floor(t/60)%24)+':'+pad(t%60);}
function status(t){document.getElementById('pj-status').textContent=t||'';}
function card(big,sub,label){return '<div class="pj-card"><b>'+big+'</b><i>'+sub+'</i><span>'+label+'</span></div>';}
function utc(m){return m==null?'—':hhmm(m);}
function est(m,lon){if(m==null)return '—';var tz=Math.round(lon/15);return '≈'+hhmm(((m+tz*60)%1440+1440)%1440)+' clock ('+(tz>=0?'+':'')+tz+'h zone)';}
function day(d){var t=new Date();d.value=t.getFullYear()+'-'+pad(t.getMonth()+1)+'-'+pad(t.getDate());}
function go(){status('finding place…');
  var v=document.getElementById('pj-place').value.trim();if(!v){status('⚠ type a place');return;}
  var m=v.split(',');
  var ptP;if(m.length===2){var a=parseFloat(m[0]),b=parseFloat(m[1]);ptP=(isFinite(a)&&isFinite(b)&&Math.abs(a)<=90&&Math.abs(b)<=180)?Promise.resolve({lat:a,lon:b,label:v}):Promise.reject(new Error('bad coordinates'));}
  else ptP=fetch('/api/peta/geocode?q='+encodeURIComponent(v)).then(function(x){return x.json();}).then(function(j){if(!j.ok||!j.results||!j.results.length)throw new Error(j.error||'place not found');return {lat:j.results[0].lat,lon:j.results[0].lon,label:j.results[0].label};});
  ptP.then(function(p){var date=document.getElementById('pj-date').value||new Date().toISOString().slice(0,10);
    status('computing…');
    return fetch('/api/peta/sun?lat='+p.lat+'&lon='+p.lon+'&date='+date).then(function(x){return x.json();}).then(function(j){if(!j.ok)throw new Error(j.error||'failed');return {p:p,j:j};});
  }).then(function(r){render(r.p,r.j);status('');
  }).catch(function(e){status('⚠ '+(e.message||e));});}
function render(p,j){var o=document.getElementById('pj-out');var cards='';
  if(j.polar==='day')cards='<div class="pj-card" style="grid-column:1/-1"><b>☀ The sun never sets</b><span>24 hours of daylight on '+esc(j.date)+' at '+esc(p.label)+'</span></div>';
  else if(j.polar==='night')cards='<div class="pj-card" style="grid-column:1/-1"><b>🌑 The sun never rises</b><span>polar night on '+esc(j.date)+' at '+esc(p.label)+'</span></div>';
  else cards=card(utc(j.sunriseUtc),est(j.sunriseUtc,p.lon),'sunrise')
    +card(utc(j.noonUtc),est(j.noonUtc,p.lon),'solar noon')
    +card(utc(j.sunsetUtc),est(j.sunsetUtc,p.lon),'sunset')
    +card(Math.floor(j.dayLengthMin/60)+'h '+pad(j.dayLengthMin%60)+'m','day length','from horizon to horizon');
  o.innerHTML=cards;
  var ex=(j.civilDawnUtc!=null)?('Civil twilight: dawn '+utc(j.civilDawnUtc)+' UTC, dusk '+utc(j.civilDuskUtc)+' UTC — '):'';
  document.getElementById('pj-extra').textContent=p.label+' · '+j.date+' · sun declination '+j.declDeg.toFixed(2)+'° · equation of time '+(j.eqTime>=0?'+':'')+j.eqTime.toFixed(1)+' min. '+(j.civilDawnUtc==null&&j.polar?'(No civil twilight — the sun stays '+(j.polar==='day'?'up':'down')+' all day.)':ex);
  }
day(document.getElementById('pj-date'));
document.getElementById('pj-go').onclick=go;
document.getElementById('pj-place').addEventListener('keydown',function(e){if(e.key==='Enter')go();});
})();</script>`;
  return worldDoc({
    title: 'Sunrise & Sunset Calculator — Day Length and Twilight Anywhere on Earth | Tukuk-OS',
    desc: 'Compute sunrise, sunset, solar noon, day length and civil twilight for any place and any date. Almanac-accurate solar arithmetic, polar cases reported honestly, free with no account or API key.',
    selfUrl: 'https://tukuk.org/peta/matahari',
    heroTitle: '🌅 Sunrise & Sunset', heroSub: 'Any place · any date · almanac math computed from arithmetic, not an API',
    css: PJ_CSS, body: body + script,
    ld: JSON.stringify({
      '@context': 'https://schema.org', '@type': 'WebApplication', name: 'Tukuk Sunrise & Sunset Calculator',
      applicationCategory: 'UtilityApplication', operatingSystem: 'Web browser',
      description: 'Sunrise, sunset, solar noon, day length and civil twilight calculator for any location on Earth and any date.',
      url: 'https://tukuk.org/peta/matahari', offers: { '@type': 'Offer', price: '0', priceCurrency: 'USD' },
    }).replace(/</g, '\\u003c'),
  }, petaNav());
}

function jamPage() {
  const css = PJ_CSS + `.pj-card .c{font-variant-numeric:tabular-nums}
.pj-feat{border-color:var(--accent,#4c8dff)}`;
  const body = `<p><b>What time is it there?</b> Live clocks for the world’s major cities, ticking every second, plus any city you search — with each place’s true UTC offset <i>right now</i> (daylight saving included, because the calculations come from the IANA time zone database your browser already ships) and the difference from your own clock. No account, no widget, nothing sent anywhere except the city name you type.</p>
  <div class="peta-form">
    <label>City <input id="pj-place" type="text" placeholder="e.g. Tokyo" autocomplete="off"></label>
    <button class="peta-btn primary" id="pj-go" type="button">Add clock</button>
    <span id="pj-status"></span>
  </div>
  <div id="pj-out" class="pj-out"></div>
  <noscript><p>JavaScript is required — a clock that lies about the time is worse than none. Everything else on tukuk.org works without it; the <a href="/peta/matahari">sunrise calculator</a> is pure server maths.</p></noscript>
  <h2 class="section-title">Why “the time in ___” is a hard question</h2>
  <p>Longitude gives you the sun, but <b>politicians give you the clock</b>. Zones bend around borders, provinces split in half, and daylight saving starts and ends on dates each parliament invents — the offset of a city is therefore a <i>lookup in a database of history and law</i>, not arithmetic. That database (the IANA tzdb) lives inside every modern browser, which is why this page can answer accurately for <i>any</i> city without a time-zone API of its own. For the full story of how the world’s clocks got this way, read <a href="/blog/time-zones-explained">time zones explained</a>.</p>
  <h2 class="section-title">Sun time vs clock time</h2>
  <p>The ☀️/🌙 on each card is the rough daylight guess (6 pm-ish horizon rule on the <i>target’s</i> clock). The sun itself is stricter: for the actual sunrise, sunset and daylight length anywhere on Earth, use the <a href="/peta/matahari">sunrise &amp; sunset calculator</a> — and if you are planning a call across the map, the <a href="/peta/jarak">distance calculator</a> tells you how far the signal (or the flight) has to go. Related: <a href="/peta">maps &amp; navigation</a>.</p>
  <p class="meta">City names resolved by the Open-Meteo geocoder (cached on our server, one request per city per day); times, offsets and DST computed locally by your browser’s Intl API from the IANA time zone database.</p>`;
  const script = `<script>(function(){
var CITY=[['Singapore','Asia/Singapore'],['Tokyo','Asia/Tokyo'],['Sydney','Australia/Sydney'],['Mumbai','Asia/Kolkata'],['Dubai','Asia/Dubai'],['Moscow','Europe/Moscow'],['Cairo','Africa/Cairo'],['Johannesburg','Africa/Johannesburg'],['London','Europe/London'],['Paris','Europe/Paris'],['New York','America/New_York'],['Sao Paulo','America/Sao_Paulo'],['Los Angeles','America/Los_Angeles']];
function esc(x){return String(x).replace(/[&<>]/g,function(c){return({'&':'&amp;','<':'&lt;','>':'&gt;'})[c];});}
function status(t){document.getElementById('pj-status').textContent=t||'';}
function offsetOf(tz){try{var s=new Intl.DateTimeFormat('en-US',{timeZone:tz,timeZoneName:'shortOffset'}).formatToParts(new Date());
  var z=(s.filter(function(p){return p.type==='timeZoneName';})[0]||{}).value||'GMT+0';
  var m=z.match(/GMT([+-]?)(\\d{1,2})(?::(\\d{2}))?/);if(!m)return 0;
  return (m[1]==='-'?-1:1)*(Number(m[2])+Number(m[3]||0)/60);}catch(e){return null;}}
function fmtIn(tz){try{var p=new Intl.DateTimeFormat('en-GB',{timeZone:tz,hour12:false,weekday:'short',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',second:'2-digit'}).formatToParts(new Date());
  var o={};p.forEach(function(x){o[x.type]=x.value;});
  return {h:Number(o.hour)%24,text:(''+o.hour).padStart(2,'0')+':'+o.minute+':'+o.second,day:o.weekday+' '+o.day+' '+o.month};}catch(e){return null;}}
function card(name,tz,you,feat){var f=fmtIn(tz);var off=offsetOf(tz);if(!f||off===null)return '';
  var diff=Math.round((off-you)*4)/4;
  var rel=diff===0?'your time':(diff>0?'+':'')+diff+' h';
  var icon=(f.h>=6&&f.h<18)?'☀️':'🌙';
  return '<div class="pj-card'+(feat?' pj-feat':'')+'"><b class="c">'+f.text+'</b><i>'+icon+' '+esc(name)+(feat?' · '+esc(f.day):'')+'</i><span>UTC'+(off===0?'+0':(off>0?'+':'')+off)+' · '+rel+(feat?'':' · '+f.day)+'</span></div>';}
function render(){var mine=offsetOf(Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC');if(mine===null)mine=0;
  var out=window.__jamCity?card(window.__jamCity.name+', '+window.__jamCity.country,window.__jamCity.tz,mine,true):'';
  out+=CITY.map(function(c){return card(c[0],c[1],mine,false);}).join('');
  document.getElementById('pj-out').innerHTML=out;}
function go(){var v=document.getElementById('pj-place').value.trim();if(!v){status('⚠ type a city');return;}status('looking up…');
  fetch('/api/peta/city?q='+encodeURIComponent(v)).then(function(x){return x.json();}).then(function(j){
    if(!j.ok)throw new Error(j.error||'not found');window.__jamCity=j;status('');render();
  }).catch(function(e){status('⚠ '+(e.message||e));});}
document.getElementById('pj-go').onclick=go;
document.getElementById('pj-place').addEventListener('keydown',function(e){if(e.key==='Enter')go();});
render();setInterval(render,1000);
})();</script>`;
  return worldDoc({
    title: 'World Clock — Live Time in Any City, With Real UTC Offsets & Daylight Saving | Tukuk-OS',
    desc: 'See the current time in the world’s major cities and any city you search, with exact UTC offsets including daylight saving and the difference from your own clock. Free, no account, uses the IANA time zone database in your browser.',
    selfUrl: 'https://tukuk.org/peta/jam',
    heroTitle: '🕰️ World Clock', heroSub: 'Any city · ticking now · offsets & DST from the IANA time zone database',
    css, body: body + script,
    ld: JSON.stringify({
      '@context': 'https://schema.org', '@type': 'WebApplication', name: 'Tukuk World Clock',
      applicationCategory: 'UtilityApplication', operatingSystem: 'Web browser',
      description: 'Live world clock for any city with true UTC offsets, daylight saving and difference from the visitor’s clock.',
      url: 'https://tukuk.org/peta/jam', offers: { '@type': 'Offer', price: '0', priceCurrency: 'USD' },
    }).replace(/</g, '\\u003c'),
  }, petaNav());
}

